/* 自动生成，请勿手工修改。来源：DSH math/math-exam；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"m-exa-shijuan-jiegou","title":"广州中考数学试卷结构与时间分配","subtitle":"中考 · 应试策略","grade":"all","tags":["中考应试","应试策略"],"blocks":[{"type":"note","title":"教材章节","text":"中考 · 应试策略"},{"type":"note","title":"一句话概述","text":"认清150分卷的分值结构与题位难度梯度，把120分钟用在得分率最高的地方。"},{"type":"h","text":"核心概念"},{"type":"p","text":"2027—2029年试卷分值结构（官方口径）：据广州市教育局2025年12月5日印发的《2027—2029年广州市初中学业水平考试录取计分科目考试实施方案》，数学满分由120分提高到150分，考试时长不变，仍为120分钟。方案原文的表述是「题型题量不变、考试时长不变、优化分值结构」，通过提高选择题和填空题的单题分值来实现从120分到150分的平稳过渡；方案明确客观题（选择题与填空题）总分值为64分，占全卷42.7%，而现行方案中客观题占比为40%。来源：广州市教育局官网政策解读（2025年12月）。"},{"type":"p","text":"现行120分试卷结构（2024—2026年使用）：满分120分、用时120分钟。第一大题选择题10小题，每小题3分，共30分；第二大题填空题6小题，每小题3分，共18分；第三大题解答题9小题，共72分。客观题合计48分，占全卷的40%，与官方所述「现行方案中客观题占比（40%）」完全吻合，可交叉验证该结构。"},{"type":"p","text":"150分卷的逐题分值推算：官方只公布客观题合计64分、且题量不变，未逐题公布分值。按客观题共16小题（10选择+6填空）平均推算，每小题约4分，即选择题约40分、填空题约24分；解答题合计约 150-64=86 分。此为推算值，具体以当年官方印发的试卷结构说明为准。"},{"type":"p","text":"客观题分值上升意味着什么：单题从3分提到约4分后，一道选择题的分量已接近一道基础解答题。过去「错一道选择不心疼」的心态必须改掉：客观题错3题，损失的分数相当于丢掉一整道压轴题的最后一问。基础板块的准确率，直接决定总分层级。"},{"type":"p","text":"题位与难度梯度的对应关系：1—16题是客观题，以基本概念与基本运算为主；17—22题是基础解答题，通常依次为解不等式（组）、几何证明、代数式化简求值、统计与概率、实际应用等；23题多为作图与几何探究，24题函数综合，25题几何压轴。据南方都市报2026年7月对广州中考数学的专家点评：1—22题难度适中，23题有新意，24题含参计算，25题保持区分度，整体呈「重基础、微创新、稳收官」的格局。"},{"type":"p","text":"120分钟的时间预算：150分对应120分钟，平均每1分约0.8分钟。建议：客观题16题控制在30—35分钟，17—22题用35—40分钟，23—25题留足40分钟，最后预留5—8分钟检查答题卡与关键计算。注意官方明确说明「中考数学重在考查思维品质和解决问题的能力，而非解题速度」，但考场时间的分配仍必须由自己主动掌控。"},{"type":"p","text":"失分结构的典型分布：广州卷的失分通常集中在三处：一是客观题因审题或计算粗心丢掉基础分；二是中档解答题因过程跳步被扣过程分；三是压轴题因时间不够而空白，或只写出第一问。前两处是可以靠训练完全避免的，第三处则要靠时间预算与分段得分策略。"},{"type":"note","title":"中考考法","text":"把时间预算执行成考场动作\n开考先在草稿纸写下各段截止时刻：客观题到约第 35 分钟、17—22 题到约第 75 分钟。每完成一个板块看一次表，落后超过 5 分钟就缩短验算、直接进入下一题，不靠临场感觉计时。"},{"type":"note","title":"中考考法","text":"超时跳过的动作标准\n单题实际用时达到建议用时的 1.5 倍仍无清晰思路，立即在题号上画圈、把已想到的条件写在草稿纸固定区域，然后翻页；返回时优先做画圈题中「再读一遍就有思路」的题。"},{"type":"note","title":"中考考法","text":"压轴题的分段得分操作\n24、25 题先扫三问：第一问通常是代入或基础证明，必须拿；第二问尽力写全关键步骤；第三问超时就写设元与关系式等有效片段，绝不整题留白，每一问都独立写「解」与结论。"},{"type":"note","title":"中考考法","text":"收尾五分钟的固定检查清单\n最后 5 分钟只做三件事：核对答题卡题号与填涂是否一一对应，重算客观题中拿不准的 2—3 题，检查解答题单位、取值范围与「答」句；不临时重做整题。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["每题限时预算","s 为题目分值（分），t 为该题建议用时（分钟）。","4分的客观题约3.2分钟，8分的中档解答题约6.4分钟，12分的压轴题约9.6分钟。超时1.5倍即应果断跳过并标记。"],["客观题得分率","m 为客观题实得分，64 为2027—2029年方案公布的客观题总分。","客观题是最可控的分数段，建议把 r≥0.9 定为底线；低于 0.8 说明基础概念有系统漏洞，应先补基础而非刷压轴。"],["解答题得分率（推算）","n 为解答题实得分，86 为按 150-64 推算出的解答题总分。","以 86 分为分母是为了明确「解答题才是拉分主战场」，但该分母属推算值，实际以官方试卷为准。"],["总分合成","M 为客观题得分（满分64），N 为解答题得分（推算满分86）。","按此结构自查：若客观题拿满64分、解答题只需拿到总分的一半，卷面就已经过百，可见基础板块的战略地位。"]]},{"type":"note","title":"例题","text":"某次模拟考中，小明在选择题最后一题（4分）上连续思考了9分钟，仍未确定答案，最终随手选了一个。紧接着的填空题最后一题和一道8分的解答题他都没时间完整作答，白白丢了9分。请计算：他为这4分付出的「时间代价」折算成分数是多少？这类取舍是否划算？"},{"type":"list","title":"解题步骤","items":["先算出本次考试每分对应的平均时间：全卷150分、时长120分钟，故每分约 120÷150=0.8 分钟。","他在该题上花了9分钟。按平均节奏，9分钟本应完成的分值为 9÷0.8=11.25 分。","也就是说，他用「本可产出11.25分」的时间，去博一个只有4分、且把握不大的题。","更关键的是后续连锁损失：因为时间被挤占，他丢掉了约9分的可得分。","结论：这道题的期望收益远低于机会成本，属于典型的「沉没成本陷阱」。正确做法是超过约5分钟仍无清晰思路就标记跳过，先完成后面确定能拿分的题目。"]},{"type":"p","text":"答案：时间代价折算约11.25分，加上连锁丢失的约9分，为4分难题付出的实际代价接近20分，明显不划算。"},{"type":"note","title":"方法小结","text":"考场上的判断标准不是「这道题难不难」，而是「我这段时间用来做别的题，期望得分是否更高」。"},{"type":"note","title":"例题","text":"某同学在一次150分模拟卷中，客观题（16小题）得56分，解答题得60分。请计算他的总分以及两段的得分率，并判断他下一步的提分重点在哪一段。"},{"type":"figure","figure":{"id":"fig-m-exa-jiegou-1","title":"客观题与解答题得分率对比","caption":"客观题 56/64 = 87.5%，解答题 60/86 ≈ 69.8%——解答题失分更多，是提分重点","view":"wide","alt":"两条水平得分率条形图：客观题条按 56 除以 64 填充至约 87.5%，解答题条按 60 除以 86 填充至约 70%，底部有 0%、50%、100% 刻度","prims":[{"t":"line","x1":14,"y1":20,"x2":14,"y2":62,"tone":"muted"},{"t":"line","x1":52,"y1":20,"x2":52,"y2":62,"dashed":true,"tone":"muted"},{"t":"line","x1":90,"y1":20,"x2":90,"y2":62,"dashed":true,"tone":"muted"},{"t":"rect","x":14,"y":24,"w":66.5,"h":10,"tone":"main","fill":true},{"t":"rect","x":14,"y":24,"w":76,"h":10,"tone":"main"},{"t":"rect","x":14,"y":48,"w":53,"h":10,"tone":"accent","fill":true},{"t":"rect","x":14,"y":48,"w":76,"h":10,"tone":"accent"},{"t":"text","x":12,"y":31,"text":"客观题","size":3.2,"anchor":"end"},{"t":"text","x":12,"y":55,"text":"解答题","size":3.2,"anchor":"end"},{"t":"text","x":47,"y":31.5,"text":"56/64 = 87.5%","size":3.2,"anchor":"middle"},{"t":"text","x":40.5,"y":55.5,"text":"60/86 = 69.8%","size":3.2,"anchor":"middle"},{"t":"text","x":14,"y":68,"text":"0%","size":3,"anchor":"middle"},{"t":"text","x":52,"y":68,"text":"50%","size":3,"anchor":"middle"},{"t":"text","x":90,"y":68,"text":"100%","size":3,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["总分：56+60=116 分。","客观题得分率：56÷64≈0.875，即87.5%。","解答题得分率（以推算的86分为分母）：60÷86≈0.698，约69.8%。","对比两段得分率：客观题损失8分，解答题损失约26分，解答题是主要失分源。","但需进一步分辨：解答题失分若主要在中档题（17—22题）的过程与计算上，提分会比攻压轴题快得多。","结论：该同学的提分顺序应为「先消灭客观题与中档解答题的粗心失分，再攻压轴题的第一、二问」，而不是一开始就死磕最后两题。"]},{"type":"p","text":"答案：总分116分；客观题得分率87.5%，解答题得分率约69.8%。提分重点在解答题，尤其是中档题的过程规范与计算准确率。"},{"type":"note","title":"方法小结","text":"分析成绩时要把「不会做」和「会做但做错」分开统计，后者才是短期内涨分最快的部分。"},{"type":"note","title":"例题","text":"考场上，小东站在第 14 题（填空题倒数第二题，按推算约 4 分）前已思考 6 分钟，仍没有清晰思路；此时开考刚过 32 分钟，他的客观题还剩第 16 题未做。请按时间预算规则给出小东此刻应执行的动作，并说明返回处理这道题的顺序。"},{"type":"list","title":"解题步骤","items":["怎么想到：先对照限时标准判断是否触发跳过条件，而不是继续在脑中试思路。该题建议用时约 4×0.8=3.2 分钟，1.5 倍约为 5 分钟。","他已用 6 分钟，超过 5 分钟的跳过线；此刻立刻在第 14 题题号上画圈，把已推出的条件简要抄写到草稿纸的「标记区」，翻页继续做第 16 题。","客观题整体应在第 35 分钟前后结束，他只落后约 3 分钟，跳过第 14 题后节奏即可回到预算内，不必压缩 17—22 题的时间。","第二轮返回时，不按题号顺序、而按把握程度处理：先做再读一遍就能续上思路的标记题，第 14 题若仍无突破，就把能确定的特殊值、图形关系写上，争取部分结论，不留全空。"]},{"type":"p","text":"答案：小东应立即标记并跳过第 14 题，先完成第 16 题；第二轮返回时优先处理把握最大的标记题，第 14 题仍不会则写出有效片段后放弃。"},{"type":"note","title":"方法小结","text":"跳过不是失败而是固定程序：触发条件只有一个——用时达到建议用时的 1.5 倍仍无清晰思路，与题目分值、个人情绪无关。"},{"type":"note","title":"例题","text":"某次模拟卷第 25 题为几何压轴，三小问按推算分别约为 4 分、4 分、4 分（共约 12 分，分值为推算）。甲同学用约 15 分钟完整做出前两问、第三问留白；乙同学在第三问上死磕约 20 分钟未得分，第二问未写，还挤占了第 24 题最后一问（推算约 4 分）的作答时间。仅就这两题，比较两人的得分策略。"},{"type":"list","title":"解题步骤","items":["怎么想到：压轴题多问独立给分，要按「拿到几问的分」算账，不能只看最终有没有做出最后一问。","甲在第 25 题拿到前两问约 4+4=8 分，第 24 题时间未被挤占，分数完整。","乙在第 25 题只拿到第一问约 4 分，第二问 0 分、第三问 0 分，第 24 题最后一问又因时间不够丢掉约 4 分。","仅这两题，甲比乙多保住约 8-4+4=8 分（推算）。第三问区分度最高、耗时最长，把它放到最后、保不住就放，是比死磕更优的得分顺序。"]},{"type":"p","text":"答案：甲的分段得分策略明显更优：在第 25 题稳拿前两问约 8 分且不影响第 24 题；乙约少拿 8 分（推算）。压轴题应按问取舍，先保前两问，第三问放到最后。"},{"type":"note","title":"方法小结","text":"压轴题各问往往独立给分，第一问的结论常是后两问的台阶；先扫一遍三问再动笔，按「拿第一问、争第二问、放第三问」的顺序配置时间。"},{"type":"list","title":"易错点","items":["前松后紧：开局在客观题上反复验算、追求满分，导致最后两题只剩十几分钟，压轴题连题目都读不完。","死磕难题：在一道选择题或填空题上停留超过5分钟仍不放手，把本可以拿到的解答题分数丢在了后面。","忽视客观题权重：仍按「3分一题」的旧观念对待选择题，答题随意、验算马虎，一道题就是4分，错三道相当于丢了一道大题。","解答题只写答案不写过程：广州卷解答题按步骤给分，跳过关键推理、不写「证明」「解」、不标注依据，会被扣掉大量过程分。","答题卡填涂与题号错位：做完一大题才集中涂卡，一旦错位整段作废；或在修改答案后忘记同步修改答题卡。","检查只看不算：检查时只重读一遍思路而不重新代入验算，也忽略了题目条件（如「正整数」「精确到0.01」）是否被遗漏。"]},{"type":"list","title":"解题方法","items":["三轮答题法：第一轮用约60分钟完成全部会做的题（含中档题），把没把握的题标上记号；第二轮用约35分钟攻标记题；第三轮用约15分钟检查答题卡与关键计算。","先易后难，果断跳过：单题超过预算时间1.5倍仍未形成清晰思路，立刻跳过并做记号，绝不与一道题纠缠。","按分值配时间：把每分0.8分钟作为基准节奏，定期看表校对自己是否落后于节奏，落后超过5分钟就要调整策略。","分段得分：压轴题不要因为做不出最后一问就整体放弃，第一问通常只需代入或简单推理，写完就是实打实的分数。","客观题一次做对：客观题不留检查余量，做的时候就代入原题条件复核一遍，比事后回看更省时间。","收尾必查三处：答题卡填涂是否与题号一致、关键计算是否重算一遍、应用题的答案是否带了单位且符合实际意义。"]}],"questions":[{"id":"m-exa-shijuan-jiegou-q1","type":"choice","stem":"关于2027—2029年广州中考数学试卷，下列说法正确的是（　）","answer":"B","explain":"据广州市教育局2025年12月5日印发的《2027—2029年广州市初中学业水平考试录取计分科目考试实施方案》，数学满分调整为150分，考试时长不变仍为120分钟；客观题合计64分，占全卷42.7%。方案明确「题型题量不变、考试时长不变、优化分值结构」，故A、D错误；C描述的是现行（2024—2026年）试卷结构，不是新方案。","options":["满分150分，考试时长由120分钟延长到150分钟","满分150分，考试时长仍为120分钟，客观题（选择题与填空题）合计64分","满分120分，客观题合计48分","满分150分，客观题占比提高到60%"],"difficulty":1,"tags":["试卷结构","中考政策"]},{"id":"m-exa-shijuan-jiegou-q2","type":"fill","stem":"现行（2024—2026年）广州中考数学试卷满分120分，其中选择题10小题、每小题3分，填空题6小题、每小题3分，则客观题合计为____分。","answer":"48","explain":"选择题共 10×3=30 分，填空题共 6×3=18 分，客观题合计 30+18=48 分，占全卷的 48÷120=40\\%，与官方政策解读中「现行方案中客观题占比（40%）」一致。","difficulty":1,"tags":["试卷结构","客观题"]},{"id":"m-exa-shijuan-jiegou-q3","type":"fill","stem":"2027—2029年方案公布数学客观题合计64分。若客观题的题量不变（仍为10道选择题与6道填空题），则每小题的平均分值为____分。","answer":"4","explain":"客观题共 10+6=16 小题，64÷16=4，即每小题平均约4分。官方表述为「通过提高选择题和填空题的单题分值」实现分值提升，故由现行的3分提高到约4分是合理的推算；具体分值以当年官方试卷结构说明为准。","difficulty":2,"tags":["试卷结构","推算"]},{"id":"m-exa-shijuan-jiegou-q4","type":"choice","stem":"按全卷150分、时长120分钟的平均节奏，一道12分的压轴题建议预留的作答时间约为（　）","answer":"B","explain":"平均每分约 120÷150=0.8 分钟，故12分对应 12×0.8=9.6 分钟，约10分钟。这正是「每题限时预算」的含义：压轴题虽难，但不能无限占用时间，超时后应果断转入分段得分策略。","options":["5分钟","10分钟","20分钟","30分钟"],"difficulty":1,"tags":["时间分配"]},{"id":"m-exa-shijuan-jiegou-q5","type":"short","stem":"请为一场150分、120分钟的广州中考数学考试设计一份时间分配方案，要求说明各阶段的时间、任务与取舍原则。","answer":"示例方案：第一阶段约60分钟，通做1—22题中所有会做的部分，遇到卡壳超过预算时间1.5倍的题目立即做记号跳过后置；第二阶段约35分钟，处理标记题以及23、24、25题中较有把握的小问，力争写全过程；第三阶段约15分钟，回填答题卡、复核关键计算、检查单位与题目附加条件；第四阶段约10分钟，用于压轴题的最后小问与全卷收尾。取舍原则：先保证客观题与中档解答题的正确率，压轴题以「拿第一问、争第二问、放第三问」为基本策略。","explain":"本题没有唯一标准答案，评分看方案是否自洽、可执行。设计依据是全卷150分对应120分钟、平均每分约0.8分钟，以及「客观题64分、解答题约86分」的分值结构。方案必须遵守三条硬性要求：总时间恰为120分钟；把客观题与中档解答题的正确率放在优先位置；对压轴题采用分段得分而非整体放弃。只要各阶段时间相加为120分钟、取舍原则明确、并包含最后的检查环节，即为合格方案。","difficulty":2,"tags":["时间分配","应试策略"],"rubric":["方案总时长合计为120分钟，各阶段时间分配明确、不自相矛盾","明确写出「先易后难、超时跳过」的取舍原则","把客观题与中档解答题的正确率放在压轴题之前作为优先级","提到压轴题的分段得分策略，而不是整体放弃或无限纠缠","提到最后的检查环节（答题卡、计算、单位、附加条件）"]},{"id":"m-exa-shijuan-jiegou-z1","type":"choice","stem":"数学中考中，你在一道按推算约 4 分的填空题上已用了约 6 分钟仍无清晰思路，后面还有多道解答题未做。下列处理方式最恰当的是（　）","answer":"D","explain":"该题建议用时约 4×0.8=3.2 分钟，1.5 倍约为 5 分钟，已用 6 分钟仍无清晰思路，达到跳过标准。正确动作是标记题号后立即跳过，先拿后面有把握的分数，再在第二轮返回；既不能死磕（A），也不能不做标记导致漏题（C），更不能不分析就随意放弃（B）。故选 D。","options":["继续思考直到做出来，做不出此题不往后做","立即随便填一个答案并把该题彻底忘掉","先跳过此题做后面的题，但不做任何标记","在题号上做标记后立即跳过，先完成后面有把握的题，再返回处理此题"],"difficulty":2,"tags":["时间分配","应试策略"]},{"id":"m-exa-shijuan-jiegou-z2","type":"short","stem":"一场 150 分、120 分钟的模拟考中，小华各板块实际用时如下：客观题 42 分钟，17—22 题 38 分钟，23—25 题 30 分钟，检查 10 分钟。建议时间为客观题 30—35 分钟、17—22 题 35—40 分钟、23—25 题约 40 分钟、检查 5—8 分钟。(1) 指出小华的时间安排出现了什么问题，可能造成什么后果；(2) 写出三条具体的调整动作。","answer":"(1) 客观题超时约 7—12 分钟，直接挤占了压轴题时间，使 23—25 题比预算少约 10 分钟，压轴题后两问可能来不及做；检查用满 10 分钟也未能弥补。(2) 调整动作：客观题中超过 5 分钟无思路的题标记跳过；做客观题时边做边涂卡、不做反复验算；把省下的时间留给 24、25 题的前两问。","explain":"（1）总时长 42+38+30+10=120 分钟没有超时，但结构失衡：客观题超出建议上限 42-35=7 分钟，最多超 12 分钟；压轴题板块只有 30 分钟，少于约 40 分钟的预算，压轴题后两问很可能空白。（2）调整应针对客观题提速：触发 1.5 倍限时即跳过；客观题一次做对、当场涂卡，省出检查时间；压轴题执行分段得分，先拿第一、二问。调整后如客观题压到 35 分钟，压轴题板块可恢复到约 37—40 分钟。","difficulty":2,"tags":["时间分配","应试策略"],"rubric":["指出客观题超时约 7—12 分钟、压轴题板块被挤占约 10 分钟","写出超时跳过的动作（标记、后置、先做有把握的题）","写出把时间向 24、25 题前两问倾斜或提高客观题一次正确率的具体动作"]}]},{"id":"m-exa-gaopin-kaodian","title":"中考数学高频考点清单","subtitle":"中考 · 考点梳理","grade":"all","tags":["中考应试","考点梳理"],"blocks":[{"type":"note","title":"教材章节","text":"中考 · 考点梳理"},{"type":"note","title":"一句话概述","text":"按板块清点广州卷高频考点，分清哪些必须拿满分、哪些只需争步骤分。"},{"type":"h","text":"核心概念"},{"type":"p","text":"分值结构与考点权重的对应（官方口径）：据广州市教育局2025年12月5日印发的《2027—2029年广州市初中学业水平考试录取计分科目考试实施方案》，数学满分为150分、时长120分钟，客观题合计64分、占全卷42.7%；方案同时强调题目情境创设与核心素养导向，减少单纯记忆与机械训练类试题。这意味着基础概念的准确理解比刷题量更重要。来源：广州市教育局官网政策解读（2025年12月）。"},{"type":"p","text":"现行120分卷结构与考点分布：现行卷为选择题10小题共30分、填空题6小题共18分、解答题9小题共72分，客观题合计48分占40%。这48分与72分就是考点权重的直接体现：解答题占六成，说明广州卷高度重视推理表达与综合运用，而不是单纯的知识辨认。"},{"type":"p","text":"数与代数板块的高频点：实数的概念与运算（含负无理数的判断）、科学记数法、整式与分式的运算、二次根式的化简与取值条件、因式分解、代数式化简求值。这类考点通常出现在1—3题与解答题的第一道代数题中，属于必须拿满分的板块。"},{"type":"p","text":"方程与不等式板块的高频点：一元一次不等式（组）的解法与数轴表示、分式方程的解法与检验、一元二次方程根的判别式与根与系数的关系、一元二次方程的实际应用。判别式 Δ=b²-4ac 的符号判断是近年客观题的常客，属高频且易于得分的点。"},{"type":"p","text":"函数板块的高频点：一次函数图象的平移与交点问题、反比例函数的图象位置与中心对称性质、反比例函数与一次函数的交点比较、二次函数的含参讨论与恒过定点。函数是广州卷解答题24题的固定主场，也是初高衔接的核心内容，权重高、区分度大。"},{"type":"p","text":"图形与几何板块的高频点：全等三角形与相似三角形的判定与性质、特殊平行四边形（菱形、矩形、正方形）的性质与判定、中点四边形、圆中的圆周角与切线、圆上动点的最值问题、折叠与旋转。几何既出现在中档解答题中，也构成25题的压轴骨架。"},{"type":"p","text":"统计与概率板块的高频点：统计图的选择与信息读取、平均数与加权平均数、中位数与众数、方差的比较、用列表或树状图求概率、几何概型与格点概率。这部分通常以社会情境或校园活动为背景，读题量与计算量都不小，属于「会做但容易丢分」的板块。"},{"type":"p","text":"综合实践与应用建模板块：增长率与利润问题、工程与行程问题、测量与三角函数建模（坡角、仰角、限高）、新定义与阅读探究题。这类题往往以一份研究记录或一份材料呈现，需要先从长文字中抽取数学关系再建模，是近年广州卷创新力度最大的部分。"},{"type":"note","title":"中考考法","text":"基础高频点的零失误清单\n实数运算、科学记数法、因式分解、解不等式（组）这类必考点，整理成一张约 15 行的清单逐行过关；训练时全题写过程，连续三次全对才标记过关，不把「会算」当成「不丢分」。"},{"type":"note","title":"中考考法","text":"含参题的固定讨论顺序\n见到含字母系数的方程，先讨论二次项系数是否为零（是不是一元二次方程），再算判别式定根的个数，最后才用韦达定理处理根的关系；三步顺序写在卷面上，防止漏解丢过程分。"},{"type":"note","title":"中考考法","text":"长情境题的信息抽取动作\n增长率、测量、新定义题先读问题再读材料，把材料翻译成「已知数据、所求量、等量关系」三行写在草稿纸上，关系式列全后再动笔计算，避免读到一半就列式。"},{"type":"note","title":"中考考法","text":"按错题考点分配复习时间\n错题按六个板块归类统计失分，先补「反复错且位于客观题、中档解答题」的考点，再攻函数与几何压轴；同一考点连错两次就回教材重学定义和例题，而不是再找同类新题刷。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["一元二次方程根的判别式","Δ>0 有两个不相等实根，Δ=0 有两个相等实根，Δ<0 无实数根。","必须在 a≠0 的前提下使用；含参数题要同时讨论 a=0 的退化情形，这是最常见的漏解点。"],["反比例函数的图象位置","当 k>0 时图象在第一、三象限；当 k<0 时图象在第二、四象限。","判断 k 的符号时要先由条件（如 |k|=-k）推出 k<0，再定象限，不可跳过符号判断直接看选项。"],["一次函数图象的平移","向上平移 m 个单位得 y=kx+b+m，向下平移得 y=kx+b-m。","平移只改变截距 b，不改变斜率 k；求「与线段有交点」的问题要分别代入线段两个端点，转化为关于 m 的不等式组。"],["加权平均数","f_i 为权重（可用比的形式给出，如 4:3:3）。","权重是比例而非具体人数时，可直接把比代入分子分母；算完要回答「能否据此确定名次」这类附加设问，不要只报数字。"],["概率公式","n 为所有等可能结果数，m 为事件 A 包含的结果数。","使用前提是各结果等可能；格点概率题要先把符合条件的点逐个列出，再用「符合数÷总点数」。"],["扇形面积与弧长","n 为圆心角的度数，R 为半径。","常用于圆与统计图表（扇形统计图）两类情境，注意圆心角与所占百分比之间的换算。"]]},{"type":"note","title":"例题","text":"关于 x 的一元二次方程 x²-2x+m=0 有两个相等的实数根，求 m 的值，并说明该方程在 m 取何值时有两个不相等的实数根。"},{"type":"list","title":"解题步骤","items":["写出系数：a=1，b=-2，c=m，注意 a=1≠0，方程确为一元二次方程。","计算判别式：Δ=b²-4ac=(-2)²-4×1× m=4-4m。","有两个相等实根要求 Δ=0，即 4-4m=0，解得 m=1。","判定不相等实根的条件：Δ>0，即 4-4m>0，解得 m<1。","结论：m=1 时两根相等；m<1 时有两个不相等的实数根。"]},{"type":"p","text":"答案：m=1 时有两个相等实根；m<1 时有两个不相等的实数根。"},{"type":"note","title":"方法小结","text":"判别式的使用有两步固定动作：先确认二次项系数不为零，再算 Δ 并讨论符号。漏掉第一步是含参题最常见的失分点。"},{"type":"note","title":"例题","text":"某校举行主题演讲比赛，评委从内容、能力、效果三个方面打分。甲的内容98分、能力88分、效果84分。若按内容、能力、效果 4:3:3 的比计算加权平均成绩，求甲的成绩（百分制，结果精确到0.1）。"},{"type":"list","title":"解题步骤","items":["确认权重之和：4+3+3=10，可作为分母。","分别求加权项：内容 98×4=392，能力 88×3=264，效果 84×3=252。","求和：392+264+252=908。","求加权平均：x=908÷10=90.8。","回答时须点明这是按 4:3:3 权重计算的加权平均成绩，普通的算术平均为 (98+88+84)÷3≈90.0，两者结果不同，说明权重设计会改变评价结果。"]},{"type":"p","text":"答案：甲按 4:3:3 计算的加权平均成绩为90.8分。"},{"type":"note","title":"方法小结","text":"统计题的最后往往有一句「请解释你的设计理由」，这类开放设问也要作答，否则会丢分。"},{"type":"note","title":"例题","text":"已知反比例函数 y=(k)/(x) 满足 |k|=-k 且 k≠0。请判断其图象所在的象限，并说明 k 的取值范围。"},{"type":"list","title":"解题步骤","items":["由绝对值的非负性知 |k|≥0，故 -k≥0，即 k≤0。","又已知 k≠0，所以 k<0。","反比例函数 y=(k)/(x) 的图象位置由 k 的符号决定：k>0 时在第一、三象限，k<0 时在第二、四象限。","因 k<0，故图象位于第二、四象限。"]},{"type":"p","text":"答案：k<0，图象位于第二、四象限。"},{"type":"note","title":"方法小结","text":"这类题的关键不是结论本身，而是「先由绝对值与不为零条件锁死符号」这一步，很多同学直接看选项凭印象作答而失分。"},{"type":"note","title":"例题","text":"已知关于 x 的一元二次方程 x²-3x-1=0 的两个实数根分别为 x₁、x₂。不求方程的根，求 x₁²+x₂² 与 (x₁-x₂)² 的值。"},{"type":"list","title":"解题步骤","items":["怎么想到：题目明确「不求根」，提示用根与系数的关系（韦达定理）先拿两根之和与两根之积，再把所求式整体代入。","由韦达定理：x₁+x₂=-(-3)/(1)=3，x₁x₂=(-1)/(1)=-1。","利用完全平方公式变形：x₁²+x₂²=(x₁+x₂)²-2x₁x₂=3²-2×(-1)=9+2=11。","再由 (x₁-x₂)²=(x₁+x₂)²-4x₁x₂=9-4×(-1)=9+4=13。检验：判别式 Δ=9+4=13>0，两根为一正一负且不相等，(x₁-x₂)²=13 与判别式的值一致。"]},{"type":"p","text":"答案：x₁²+x₂²=11，(x₁-x₂)²=13"},{"type":"note","title":"方法小结","text":"韦达定理的高频用法是整体代换：见到两根的对称式，先用完全平方公式变形成「两根和」与「两根积」的组合，切勿先求根再代回，既慢又容易算错。"},{"type":"note","title":"例题","text":"如图，在四边形 ABCD 中，对角线 AC=8，BD=6，且 AC⊥ BD。点 E、F、G、H 依次为边 AB、BC、CD、DA 的中点，依次连接得到四边形 EFGH。判断四边形 EFGH 的形状，并求它的面积。"},{"type":"figure","figure":{"id":"fig-m-exa-kaodian-1","title":"中点四边形示意图","caption":"对角线 AC = 8、BD = 6 且互相垂直，中点四边形 EFGH 是长 4、宽 3 的矩形，面积 12","view":"square","alt":"四边形 ABCD 的对角线 AC 等于 8 水平放置，BD 等于 6 竖直放置且互相垂直，各边中点 E、F、G、H 依次连接围成一个矩形，边长分别为 4 和 3","prims":[{"t":"poly","points":[[37.2,44],[50,34.4],[62.8,44],[50,53.6]],"closed":true},{"t":"line","x1":37.2,"y1":44,"x2":62.8,"y2":44,"dashed":true,"tone":"muted"},{"t":"line","x1":50,"y1":34.4,"x2":50,"y2":53.6,"dashed":true,"tone":"muted"},{"t":"poly","points":[[43.6,39.2],[56.4,39.2],[56.4,48.8],[43.6,48.8]],"closed":true,"tone":"accent","fill":true},{"t":"dot","x":37.2,"y":44},{"t":"text","x":33.5,"y":44,"text":"A","size":3.4,"anchor":"end"},{"t":"dot","x":50,"y":34.4},{"t":"text","x":50,"y":31,"text":"B","size":3.4,"anchor":"middle"},{"t":"dot","x":62.8,"y":44},{"t":"text","x":66,"y":44,"text":"C","size":3.4},{"t":"dot","x":50,"y":53.6},{"t":"text","x":50,"y":58,"text":"D","size":3.4,"anchor":"middle"},{"t":"dot","x":43.6,"y":39.2,"tone":"accent"},{"t":"text","x":42,"y":37,"text":"E","size":3.2,"anchor":"end","tone":"accent"},{"t":"dot","x":56.4,"y":39.2,"tone":"accent"},{"t":"text","x":58,"y":37,"text":"F","size":3.2,"tone":"accent"},{"t":"dot","x":56.4,"y":48.8,"tone":"accent"},{"t":"text","x":58,"y":52,"text":"G","size":3.2,"tone":"accent"},{"t":"dot","x":43.6,"y":48.8,"tone":"accent"},{"t":"text","x":42,"y":52,"text":"H","size":3.2,"anchor":"end","tone":"accent"},{"t":"text","x":68,"y":41,"text":"AC = 8","size":3.2,"tone":"muted"},{"t":"text","x":52.5,"y":44.5,"text":"BD = 6","size":3,"tone":"muted"},{"t":"text","x":50,"y":68,"text":"EF = AC÷2 = 4，FG = BD÷2 = 3，EF ⊥ FG","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":76,"text":"矩形 EFGH 面积 = 4 × 3 = 12","size":3.2,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["怎么想到：四边中点依次相连是中点四边形，用三角形中位线定理把它的边与原四边形的两条对角线对应起来，形状由对角线是否垂直决定。","在三角形 ABC 中，EF 是中位线，故 EF∥ AC 且 EF=(1)/(2)AC=4；同理 HG∥ AC 且 HG=4，所以 EFGH 首先是平行四边形。","又 FG 是三角形 BCD 的中位线，FG∥ BD 且 FG=(1)/(2)BD=3。因 AC⊥ BD，故 EF⊥ FG，平行四边形 EFGH 有一个内角为直角，是矩形。","面积为 EF× FG=4×3=12。检验：对角线互相垂直的四边形面积为 (1)/(2)AC· BD=(1)/(2)×8×6=24，而中点四边形的面积恒为原四边形面积的一半，24×(1)/(2)=12，两种算法一致。"]},{"type":"p","text":"答案：四边形 EFGH 是矩形（长为 4、宽为 3），面积为 12"},{"type":"note","title":"方法小结","text":"中点四边形必是平行四边形，邻边分别平行于原四边形的两条对角线；对角线垂直时它变为矩形，对角线相等时变为菱形。面积恒为原四边形面积的一半，可用来快速检验。"},{"type":"list","title":"易错点","items":["把「高频」等同于「必考同一道题」：考点高频指的是知识板块反复出现，题目情境与设问方式年年变化，背题型而不懂原理会在变式中失灵。","忽视表面简单的统计与概率题：读题量大、计算步骤多，容易在「加权」「精确到」「能否确定名次」这类细节上答非所问。","含参数方程忽略二次项系数为零的退化情形：只讨论 $\\Delta$，不讨论 $a=0$，导致分类不全。","概念辨析题凭印象作答：如负无理数、平均数与加权平均数的区别、统计图适用场景，都是必须回到定义判断的题目。","只攻压轴题、放掉基础板块：客观题64分加上中档解答题的分量远大于最后两题，忽略基础板块会让总分天花板很低。"]},{"type":"list","title":"解题方法","items":["按板块建立考点清单：把考点分成「数与代数、方程与不等式、函数、图形与几何、统计与概率、综合实践」六块，每块标注自己的掌握程度，针对性补弱。","先保底再提分：先把六块中的基础概念与基本运算做到零失误，再集中火力攻函数与几何综合题。","错题按考点归类：错题本不按时间记录，而按考点归类，同一考点连续错两次就必须回课本重学概念。","回归教材：官方明确要求「依标命题」，教材例题与习题的变式是中考题的重要来源，尤其几何作图与探究题。","训练读题与信息抽取：把长文字应用题先翻译成「已知—求—关系」三行，再动手建模，避免边读边算。"]}],"questions":[{"id":"m-exa-gaopin-kaodian-q1","type":"choice","stem":"判断一元二次方程根的情况，其依据是（　）","answer":"B","explain":"根的个数由判别式的符号唯一决定：Δ>0 有两个不相等实根，Δ=0 有两个相等实根，Δ<0 无实数根。求根公式与配方都能算出根，但判断根的情况只需看 Δ 的符号，这是最省时的方法；韦达定理反映的是根与系数的关系，不用于判断根的存在性。","options":["求根公式的直接计算","判别式 Δ=b²-4ac 的符号","根与系数的关系（韦达定理）","配方后开平方"],"difficulty":1,"tags":["一元二次方程","判别式"]},{"id":"m-exa-gaopin-kaodian-q2","type":"fill","stem":"已知反比例函数 y=(k)/(x)（k≠0）满足 |k|=-k，则该函数的图象位于第____象限。","answer":"二、四|二四|第二、四象限|第二四象限","explain":"由 |k|=-k 知 -k≥0，即 k≤0；又 k≠0，所以 k<0。k<0 时反比例函数图象位于第二、四象限。","difficulty":2,"tags":["反比例函数","图象与性质"]},{"id":"m-exa-gaopin-kaodian-q3","type":"choice","stem":"下列考点中，近年广州中考最常在试卷后段（第24、25题）作为压轴内容考查的是（　）","answer":"C","explain":"广州卷的后两题长期稳定为「一道函数综合 + 一道几何综合」。据南方都市报2026年7月对广州中考数学的专家点评，第24题考查恒过定点问题与含参计算，第25题在翻折背景下用动点轨迹求线段长，均属函数与几何的综合考查。A、B、D都是客观题位置的基础考点，不会出现在压轴位置。","options":["有理数的加减运算","科学记数法","二次函数含参讨论与几何图形综合","简单几何体的三视图"],"difficulty":1,"tags":["考点分布","压轴题"]},{"id":"m-exa-gaopin-kaodian-q4","type":"fill","stem":"某次比赛按内容、能力、效果 4:3:3 的比例计算成绩。甲的三项成绩依次为98分、88分、84分，则甲的加权平均成绩为____分。","answer":"90.8","explain":"x=(98×4+88×3+84×3)÷(4+3+3)=(392+264+252)÷10=908÷10=90.8（分）。注意权重之和为10，不能错误地除以3。","difficulty":2,"tags":["统计","加权平均数"]},{"id":"m-exa-gaopin-kaodian-q5","type":"short","stem":"请从「函数」「图形与几何」「统计与概率」三个板块中各选一个高频考点，分别说明它的典型考查方式以及你在考场上应当注意的关键动作。","answer":"示例：（1）函数板块的反比例函数图象与性质——典型考法是由条件确定 $k$ 的符号，再判断图象象限，或与一次函数联立比较函数值大小；关键动作是先锁定 $k$ 的符号再选答案，不用特例硬套。（2）图形与几何板块的中点四边形——典型考法是给出菱形、矩形或一般四边形的面积，求各边中点连线所得四边形的形状与面积；关键动作是回忆「中点四边形是平行四边形，其面积为原四边形面积的一半，且形状由原四边形对角线的关系决定」。（3）统计与概率板块的加权平均数——典型考法是在比赛评分、招聘考核等情境中按比计算加权平均；关键动作是权重和作分母、并回答设问中的开放性追问。","explain":"本题为开放性归纳题，评分看三点：是否覆盖了要求的三个板块且各选一个具体考点；是否说清了「怎么考」（典型考查方式）；是否给出了考场上可执行的关键动作。判断答案是否合格的标准是可操作性——若某条只写了「要认真审题」这类空话，就没有达到要求；若能写出如「见到反比例函数先定 k 的符号」「中点四边形的面积恒为原四边形的一半」这类可直接调用的结论，才算合格。","difficulty":2,"tags":["考点梳理","方法总结"],"rubric":["三个板块各选一个考点，不重复、不遗漏","每个考点都写出了具体的典型考查方式（说明「怎么考」）","每个考点都给出了考场上可直接执行的关键动作（说明「怎么做」）","表述准确，使用了规范的数学名词"]},{"id":"m-exa-gaopin-kaodian-z1","type":"choice","stem":"距离中考还有一个月，小琳整理错题时发现，「一元一次不等式（组）」这一考点在三次模考中连续失分，且错的都是中档解答题。下列后续做法最恰当的是（　）","answer":"C","explain":"同一考点连续错两次以上，说明概念或解法有系统漏洞，正确动作是回教材重学、再用同类题验证直至稳定全对；而且该考点位于中档解答题，修复后提分最快。A 用压轴题带基础漏洞效率低，B 背答案无法应对变式，D 主动放弃高频中档题不符合先保底的策略。故选 C。","options":["继续大量刷新的压轴题，在难题中顺便解决这个问题","把错题答案抄一遍并背下来，避免再遇到同样的题","回归教材重学不等式（组）的解法与数轴表示，找同类基础题与中档题限时训练直至连续全对","该考点分值不高，考试时把相关题目留到最后凭运气作答"],"difficulty":2,"tags":["考点梳理","复习策略"]},{"id":"m-exa-gaopin-kaodian-z2","type":"short","stem":"下表是小文近三次 150 分制数学模考各板块的失分统计（单位：分）：数与代数（实数、整式等）依次为 4、4、5；方程与不等式依次为 6、6、5；函数依次为 7、8、7；图形与几何依次为 8、9、8；统计与概率依次为 2、2、3。(1) 分别计算五个板块三次考试的平均失分；(2) 请按「先保底、再提分」的原则，指出他下一阶段最应优先补的一个板块，并写出两条可执行的训练动作。","answer":"(1) 平均失分依次为：数与代数约 4.3 分，方程与不等式约 5.7 分，函数约 7.3 分，图形与几何约 8.3 分，统计与概率约 2.3 分。(2) 应优先补方程与不等式：其失分集中在客观题与 17—22 题的中档位置，修复快、性价比高；函数与几何失分虽多但主要在压轴小问。训练动作：①每天限时完成 2 道解分式方程或不等式（组）的中档题，完整书写检验与数轴表示；②把三次模考中该板块的 6 道错题按错因归类，重学教材对应章节后再独立重做一遍。","explain":"（1）平均数分别为 (4+4+5)÷3≈4.3，(6+6+5)÷3≈5.7，(7+8+7)÷3≈7.3，(8+9+8)÷3≈8.3，(2+2+3)÷3≈2.3。（2）几何板块平均失分最多（约 8.3 分），但其中大头在 24、25 题压轴小问，短期提升慢；方程与不等式平均失分约 5.7 分且题目位于客观题与中档解答题，属于「会做但容易丢分」的可修复失分，按先保底原则应优先解决。判定答案是否合理，看是否依据平均失分与题位位置两个维度排序，且训练动作具体、可检验。","difficulty":2,"tags":["考点梳理","复习策略","数据分析"],"rubric":["正确算出五个板块的平均失分（约 4.3、5.7、7.3、8.3、2.3 分）","结合失分数量与题位位置说明优先补方程与不等式（或论证充分地选择其他板块）","写出两条具体可执行、可检验的训练动作"]}]},{"id":"m-exa-xuanze-tiankong","title":"选择填空的速解技巧","subtitle":"中考 · 题型突破","grade":"all","tags":["中考应试","题型突破"],"blocks":[{"type":"note","title":"教材章节","text":"中考 · 题型突破"},{"type":"note","title":"一句话概述","text":"客观题占全卷四成以上，用特值、排除、数形结合把16道题压缩进30分钟。"},{"type":"h","text":"核心概念"},{"type":"p","text":"客观题的分值与权重（官方口径）：据广州市教育局2025年12月5日印发的《2027—2029年广州市初中学业水平考试录取计分科目考试实施方案》，数学满分150分、时长120分钟，客观题（选择题与填空题）总分值为64分，占全卷42.7%；方案明确「题型题量不变、考试时长不变、优化分值结构」，通过提高选择题和填空题的单题分值完成分值过渡。单题分值提高后，客观题的错误代价显著上升。来源：广州市教育局官网政策解读（2025年12月）。"},{"type":"p","text":"现行卷客观题题量：现行（2024—2026年）卷为选择题10小题共30分、填空题6小题共18分，客观题合计16小题48分；新方案题量不变，仍为16小题，但合计提高到64分，平均每题约4分。"},{"type":"p","text":"特值法（特殊值代入）：当题目涉及字母取值范围的判断、不等式是否成立、代数式是否恒等时，选取满足条件的特殊值代入各选项逐一检验。选值要兼顾正负、零与非零、整数与分数，且必须至少代入两组值才能排除。适用于「一定成立」「取值范围」类选择题。"},{"type":"p","text":"排除法（代入选项验证）：不从正面推导，而是把四个选项逐个代回原题条件检验。尤其适合含参方程、函数图象、几何图形判定等题目。若能先由明显条件排除两个选项，剩下一对再用特值或图象区分，效率最高。"},{"type":"p","text":"数形结合法：把代数条件转化为图象上的位置关系，或把图形关系转化为坐标计算。典型如：由一次函数图象经过的象限反推 k、b 的符号；由抛物线与 x 轴交点反推对称轴；由直线与线段有交点转化为端点代入求参数范围。"},{"type":"p","text":"特殊位置法（极端法与一动一静）：对于动点、图形旋转或翻折的最值问题，可让动点运动到端点、中点等特殊位置，或取图形的极端形状，快速猜出答案或验证结论。此法常用于「周长最小值」「面积最大值」类问题的预判，但要注意只有在结论连续变化时才可直接代入特殊位置。"},{"type":"p","text":"量纲与估算检验：算出答案后先做合理性检验：长度是否可能为负、概率是否在 0 到 1 之间、增长率是否超过 100\\%、三角形两边之和是否大于第三边。许多错误答案正是通过这一步被迅速剔除。"},{"type":"p","text":"填空题的书写规范：填空题只认最终结果，格式必须精确：答案要化成最简形式（分式、二次根式、比的化简），带单位的题目要带单位，题目要求「精确到0.01」就必须保留两位小数。多解情况下答案要写全，缺一个即判错。"},{"type":"note","title":"中考考法","text":"动笔前先给题目归类\n读题后先在题号旁标一个字：「值」（特值）、「排」（代入排除）、「图」（画草图）、「端」（特殊位置）。归类后直接调用对应工具，避免每题都从正面硬推，客观题平均每题可省半分钟以上。"},{"type":"note","title":"中考考法","text":"特值取值覆盖正负零\n取两组满足条件的特殊值，刻意覆盖正数、负数、0 与真分数（如 -1、0、12、2）；两组值检验后仍成立的选项才入选，若两组结果不一致，说明该选项不一定成立。"},{"type":"note","title":"中考考法","text":"图象题画草图定点定线\n拿到函数图象题先在草稿纸画草图，标出与两坐标轴的交点、顶点或对称轴、特殊点，再把每个选项翻译成图上的位置关系；图一画准，符号类选项通常可直接排除两个。"},{"type":"note","title":"中考考法","text":"填空题交卷前三查\n誊写答案前固定检查三项：结果是否为最简（分式约分、根式化简），是否漏写单位或精确度，多解题是否把各种情况写全；三查共约十秒钟，却能挡住多数非知识性失分。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["平方差与完全平方","用于代数式化简、特值法检验与整体代入。","特值法检验整式运算时，优先取 a=1、b=-1 或 a=2、b=12，能同时覆盖符号与分数情形。"],["二次函数的顶点式","顶点为 (h,k)，对称轴为直线 x=h。","选择与填空中的平移、最值、图象判定题，先化为顶点式再比较，比逐个代入点坐标更快。"],["关于原点与坐标轴对称的点","分别是关于原点、关于 x 轴、关于 y 轴对称的点的坐标。","反比例函数图象关于原点中心对称，是「中心对称推参数关系」类选择题的解题依据。"],["反比例函数 k 的几何意义","双曲线上任一点向两坐标轴作垂线，与坐标轴围成的矩形面积为 |k|。","常用于结合三角形的面积反求 k；注意三角形面积是 (|k|)/(2)，容易与矩形面积混淆。"],["根的判别式","Δ≥0 有实根，Δ=0 有两等根，Δ<0 无实根。","含参填空题求「有两个相等实根」时，解 Δ=0 得到的 m 还要代回检验原方程是否退化。"]]},{"type":"note","title":"例题","text":"已知 m<n<0，则下列不等式一定成立的是（　）\nA. m²<n²\nB. 1m<1n\nC. m+n<2n\nD. (m)/(n)<1"},{"type":"list","title":"解题步骤","items":["这是典型的「一定成立」型选择题，首选特值法。取 m=-2，n=-1，满足 m<n<0。","检验A：m²=4，n²=1，4<1 不成立，排除A。","检验B：1m=-0.5，1n=-1，-0.5<-1 不成立，排除B。（负数取倒数后大小关系反转，这是高频易错点。）","检验D：(m)/(n)=(-2)/(-1)=2>1，故 (m)/(n)<1 不成立，排除D。","检验C：m+n=-3，2n=-2，-3<-2 成立。再从代数角度确认：m<n 两边同时加 n 得 m+n<2n，对一切 m<n 恒成立。","结论：选C。"]},{"type":"p","text":"答案：C"},{"type":"note","title":"方法小结","text":"特值法必须代入至少两组不同的值再下结论；本题C还能用不等式性质正面证明，两者相互印证最稳妥。"},{"type":"note","title":"例题","text":"已知二次函数 y=ax²+bx+c 的图象开口向下，且经过点 (-1,0) 与 (3,0)。则下列结论正确的是（　）\nA. a>0\nB. 图象的对称轴为直线 x=1\nC. c<0\nD. 当 x>1 时，y 随 x 的增大而增大"},{"type":"list","title":"解题步骤","items":["由「开口向下」直接得 a<0，排除A。","由经过 (-1,0)、(3,0) 知对称轴为 x=(-1+3)/(2)=1，故B正确。","用交点式写出解析式：y=a(x+1)(x-3)=a(x²-2x-3)=ax²-2ax-3a，比较得 c=-3a。","因 a<0，所以 c=-3a>0，排除C。","抛物线开口向下，对称轴 x=1 是最高点所在位置，故当 x>1 时 y 随 x 增大而减小，排除D。","结论：选B。"]},{"type":"p","text":"答案：B"},{"type":"note","title":"方法小结","text":"「开口方向 + 两根」可以快速写出交点式，比用待定系数法解三元方程组快得多，是客观题的提速关键。"},{"type":"note","title":"例题","text":"如图，反比例函数 y=(k)/(x) 的图象经过第一象限内的点 A，过点 A 分别作 AB⊥ x 轴于点 B、AC⊥ y 轴于点 C，矩形 OBAC 的面积为 6。求 k 的值；若 D 是该图象第一象限分支上另一点，过 D 作 DE⊥ x 轴于点 E，求三角形 ODE 的面积。"},{"type":"figure","figure":{"id":"fig-m-exa-xuanze-1","title":"反比例函数 k 的几何意义","caption":"矩形 OBAC 面积恒为 |k| = 6，三角形 ODE 面积恒为 |k|÷2 = 3","view":"wide","alt":"坐标系中第一象限的双曲线，点 A 坐标 2,3 处的矩形面积是 6，点 D 坐标 6,1 处与坐标轴围成的直角三角形面积是 3","prims":[{"t":"axis","x":14,"y":70,"w":56,"h":48,"xLabel":"x","yLabel":"y","origin":true,"xTicks":[{"at":0.25,"label":"2"},{"at":0.5,"label":"4"},{"at":0.75,"label":"6"}],"yTicks":[{"at":0.25,"label":"1"},{"at":0.5,"label":"2"},{"at":0.75,"label":"3"}]},{"t":"curve","points":[[24.5,22],[28,34],[35,46],[42,52],[56,58],[70,61]],"tone":"accent"},{"t":"poly","points":[[14,70],[56,70],[56,58]],"closed":true,"tone":"accent"},{"t":"rect","x":14,"y":34,"w":14,"h":36,"tone":"main","fill":true},{"t":"dot","x":28,"y":34,"tone":"accent"},{"t":"text","x":31,"y":33,"text":"A(2,3)","size":3.2,"tone":"accent"},{"t":"dot","x":56,"y":58},{"t":"text","x":59,"y":56,"text":"D(6,1)","size":3.2},{"t":"dot","x":56,"y":70},{"t":"text","x":56,"y":75,"text":"E","size":3.2,"anchor":"middle"},{"t":"text","x":21,"y":54,"text":"面积 6","size":3,"anchor":"middle"},{"t":"text","x":36,"y":63,"text":"面积 3","size":3,"tone":"accent"},{"t":"text","x":30,"y":20,"text":"y = 6/x（k > 0）","size":3.2,"tone":"accent"},{"t":"text","x":50,"y":88,"text":"矩形 OBAC 面积 = |k| = 6，故 k = 6；三角形 ODE 面积 = |k|÷2 = 3","size":3.2,"anchor":"middle"},{"t":"text","x":10.5,"y":73.5,"text":"O","size":3.2,"tone":"muted"},{"t":"text","x":28,"y":74.5,"text":"B","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":11,"y":34,"text":"C","size":3.2,"anchor":"end","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["怎么想到：题目给的是垂线与面积、没有任何点的坐标，正面求点坐标行不通，应直接调用反比例函数中 k 的几何意义。","点 A 在第一象限，矩形 OBAC 的面积为 |k|=6，且图象在第一象限说明 k>0，故 k=6。","函数解析式为 y=(6)/(x)。设点 D 的坐标为 (x_D,y_D)，则 x_Dy_D=6。","三角形 ODE 的两条直角边分别为 x_D 与 y_D，面积为 (1)/(2)x_Dy_D=(1)/(2)|k|=3。检验：任取一点如 D(2,3)，矩形面积为 6、三角形面积为 3，与结论一致。"]},{"type":"p","text":"答案：k=6；三角形 ODE 的面积为 3"},{"type":"note","title":"方法小结","text":"反比例函数图象上任意一点向两坐标轴作垂线，围成的矩形面积恒为 |k|，对应直角三角形的面积为 (|k|)/(2)；先由图象所在象限定 k 的符号，再写 k 的值。"},{"type":"note","title":"例题","text":"如图，在矩形 ABCD 中，AB=6，BC=8，点 P 是边 AD 上的一个动点，PE⊥ AC 于点 E，PF⊥ BD 于点 F。当点 P 在 AD 上运动时，PE+PF 的值是否发生变化？若不变，求这个定值。"},{"type":"figure","figure":{"id":"fig-m-exa-xuanze-2","title":"矩形对角线的动点距离","caption":"P 在 AD 上移动时，P 到两条对角线的距离之和不变，恒为 4.8","view":"square","alt":"矩形 ABCD，AB 等于 6，BC 等于 8，两条对角线相交，动点 P 在 AD 边上，P 到对角线 AC 的垂线段 PE 与到对角线 BD 的垂线段 PF 之和为定值 4.8","prims":[{"t":"poly","points":[[30,20],[63,20],[63,64],[30,64]],"closed":true},{"t":"line","x1":30,"y1":20,"x2":63,"y2":64},{"t":"line","x1":63,"y1":20,"x2":30,"y2":64},{"t":"line","x1":30,"y1":42,"x2":40.56,"y2":34.08,"dashed":true,"tone":"accent"},{"t":"line","x1":30,"y1":42,"x2":40.56,"y2":49.92,"dashed":true,"tone":"accent"},{"t":"dot","x":30,"y":20},{"t":"text","x":26.5,"y":20,"text":"A","size":3.4,"anchor":"end"},{"t":"dot","x":63,"y":20},{"t":"text","x":66,"y":20,"text":"B","size":3.4},{"t":"dot","x":63,"y":64},{"t":"text","x":66,"y":64,"text":"C","size":3.4},{"t":"dot","x":30,"y":64},{"t":"text","x":26.5,"y":64,"text":"D","size":3.4,"anchor":"end"},{"t":"dot","x":30,"y":42,"tone":"accent"},{"t":"text","x":27,"y":42,"text":"P","size":3.4,"anchor":"end","tone":"accent"},{"t":"dot","x":40.56,"y":34.08,"hollow":true,"tone":"accent"},{"t":"text","x":44,"y":33,"text":"E","size":3.2,"tone":"accent"},{"t":"dot","x":40.56,"y":49.92,"hollow":true,"tone":"accent"},{"t":"text","x":44,"y":53,"text":"F","size":3.2,"tone":"accent"},{"t":"text","x":46.5,"y":17,"text":"AB = 6","size":3.2,"anchor":"middle"},{"t":"text","x":67,"y":44,"text":"BC = 8","size":3.2},{"t":"text","x":50,"y":76,"text":"BD = √(6² + 8²) = 10，PE + PF = 6 × 8 ÷ 10 = 4.8（定值）","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":84,"text":"用面积分割：½ × 5 × PE + ½ × 5 × PF = 12","size":3.2,"anchor":"middle","tone":"muted"},{"t":"dot","x":46.5,"y":42,"tone":"muted"},{"t":"text","x":48.5,"y":39.4,"text":"O","size":3.4,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["怎么想到：结论随动点连续变化，先用特殊位置预判：让点 P 运动到端点 A，此时 PE=0，PE+PF 就等于点 A 到对角线 BD 的距离。","矩形对角线 BD=√(6²+8²)=10。用等面积法求点 A 到 BD 的距离 h：(1)/(2)×10× h=(1)/(2)×6×8，解得 h=(24)/(5)=4.8，预判 PE+PF=4.8。","严格验证：设对角线交点为 O，则 OA=OD=5。连接 OP，由面积分割 S_(△ AOP)+S_(△ DOP)=S_(△ AOD)。","代入得 (1)/(2)×5× PE+(1)/(2)×5× PF=(1)/(4)×6×8=12，即 (5)/(2)(PE+PF)=12，解得 PE+PF=(24)/(5)=4.8，与特殊位置的预判相同，故它是不随点 P 变化的定值。"]},{"type":"p","text":"答案：PE+PF 的值不变，恒为 (24)/(5)（即 4.8）"},{"type":"note","title":"方法小结","text":"特殊位置法负责「快速预判答案」，面积分割负责「严格确认」：客观题只取预判值即可，若这是解答题，则必须补上面积法证明，两步缺一不可。"},{"type":"list","title":"易错点","items":["特值法只代一组值就下结论：一组特殊值只能排除选项，不能证明结论，至少两组不同性质的值才有说服力。","忽略负数取倒数、乘方后大小关系的变化：$m<n<0$ 时 $\\frac1m>\\frac1n$、$m^2>n^2$，与正数情形正好相反。","填空题答案未化到最简：分式没约分、二次根式没化简、比没化成最简整数比，都会被判错。","多解情况漏答案：涉及等腰三角形腰与底、直角顶点位置、动点在直线或线段上的题目，常有多个解，只写一个即失分。","单位与精确度被忽略：题目要求「精确到0.01」却保留整数，或应用题答案漏写单位。","在客观题上反复验算：一道4分的选择题算了三遍，挤掉了后面解答题的时间，得不偿失。"]},{"type":"list","title":"解题方法","items":["先分类再动笔：拿到题先判断它属于「代数恒等判断」「图象性质判定」「动点最值」「实际应用计算」中的哪一类，不同类别对应不同的速解工具。","排除优先于推导：能排除三个选项就不要正面求答案，尤其在含参与图象题中，代入验证通常比完整推导快一半时间。","特殊值取「刁钻」的值：取 -2、-1、0、12、2 这类能同时检验符号、分数与零情形的值。","图象题一律先画草图：标出与坐标轴交点、顶点、对称轴，再对照选项判断，避免抽象推导出错。","答案三查：查是否最简、查是否带单位、查多解是否写全，三项动作在填空题上各只需几秒钟。"]}],"questions":[{"id":"m-exa-xuanze-tiankong-q1","type":"choice","stem":"已知 m<n<0，则下列不等式一定成立的是（　）","answer":"C","explain":"取特值 m=-2，n=-1 检验：A 中 4<1 不成立；B 中 -0.5<-1 不成立；D 中 (-2)/(-1)=2>1，故 (m)/(n)<1 不成立；C 中 -3<-2 成立。代数证明：m<n 两边同加 n 得 m+n<2n，恒成立。故选C。","options":["m²<n²","1m<1n","m+n<2n","(m)/(n)<1"],"difficulty":2,"tags":["特值法","不等式"]},{"id":"m-exa-xuanze-tiankong-q2","type":"choice","stem":"已知二次函数 y=ax²+bx+c 的图象开口向下，且经过点 (-1,0) 与 (3,0)，则下列结论正确的是（　）","answer":"B","explain":"开口向下给出 a<0，排除A与D（a<0 时在对称轴右侧 y 随 x 增大而减小）。两个与 x 轴的交点横坐标为 -1 和 3，故对称轴为 x=(-1+3)/(2)=1，B正确。由交点式 y=a(x+1)(x-3)=ax²-2ax-3a 得 c=-3a>0，排除C。","options":["a>0","图象的对称轴为直线 x=1","c<0","当 x>1 时，y 随 x 的增大而增大"],"difficulty":2,"tags":["排除法","二次函数"]},{"id":"m-exa-xuanze-tiankong-q3","type":"fill","stem":"菱形 ABCD 的面积为10，点 E、F、G、H 分别是边 AB、BC、CD、DA 的中点，则四边形 EFGH 的面积为____。","answer":"5","explain":"连接对角线 AC、BD。由三角形中位线定理，EF∥ AC 且 EF=12 AC；同理 GH∥ AC 且 GH=12 AC，故 EF∥ GH 且 EF=GH，四边形 EFGH 是平行四边形。又菱形对角线互相垂直，可推出 EF⊥ FG，故 EFGH 是矩形，其面积为原菱形面积的一半，即 10÷2=5。","difficulty":2,"tags":["中点四边形","特殊位置法"],"figure":{"id":"fig-m-exa-xuanze-3","title":"菱形各边中点连成的矩形","caption":"E、F、G、H 是菱形 ABCD 各边的中点：EFGH 的两组对边分别平行于两条对角线，且邻边互相垂直，所以它是矩形，面积是原菱形的一半","view":"square","alt":"菱形 ABCD，两条对角线 AC 与 BD 画成虚线并在交点处垂直；四条边的中点 E、F、G、H 依次相连，围成菱形内部的一个矩形。","prims":[{"t":"poly","points":[[20,45],[50,20],[80,45],[50,70]],"closed":true},{"t":"poly","points":[[35,32.5],[65,32.5],[65,57.5],[35,57.5]],"closed":true,"tone":"ok","fill":true},{"t":"line","x1":20,"y1":45,"x2":80,"y2":45,"tone":"muted","dashed":true},{"t":"line","x1":50,"y1":20,"x2":50,"y2":70,"tone":"muted","dashed":true},{"t":"line","x1":46,"y1":45,"x2":46,"y2":41,"tone":"muted"},{"t":"line","x1":46,"y1":41,"x2":50,"y2":41,"tone":"muted"},{"t":"dot","x":20,"y":45,"label":"A","labelDx":-5.4,"labelDy":2},{"t":"dot","x":50,"y":20,"label":"B","labelDx":0,"labelDy":-3.4},{"t":"dot","x":80,"y":45,"label":"C","labelDx":2.6,"labelDy":2},{"t":"dot","x":50,"y":70,"label":"D","labelDx":0,"labelDy":3.6},{"t":"dot","x":35,"y":32.5,"label":"E","labelDx":-5,"labelDy":-1.6},{"t":"dot","x":65,"y":32.5,"label":"F","labelDx":3.2,"labelDy":-1.6},{"t":"dot","x":65,"y":57.5,"label":"G","labelDx":3.2,"labelDy":3},{"t":"dot","x":35,"y":57.5,"label":"H","labelDx":-5,"labelDy":3},{"t":"text","x":50,"y":88,"text":"EFGH 是矩形，面积 = 菱形面积的一半","anchor":"middle","size":3.6,"tone":"ok"}]}},{"id":"m-exa-xuanze-tiankong-q4","type":"fill","stem":"若关于 x 的方程 x²-2x+m=0 有两个相等的实数根，则 m=____。","answer":"1","explain":"二次项系数为1，不为零，方程确为一元二次方程。由 Δ=b²-4ac=(-2)²-4×1× m=4-4m=0 得 m=1。代回检验：x²-2x+1=0，即 (x-1)²=0，两根均为1，确为两等根。","difficulty":1,"tags":["判别式","填空题规范"]},{"id":"m-exa-xuanze-tiankong-q5","type":"choice","stem":"已知一次函数 y=kx+b 的图象经过第一、二、四象限，则 k、b 满足（　）","answer":"B","explain":"画草图判断：图象不经过第三象限，说明函数单调递减，故 k<0；图象与 y 轴交点在正半轴，故 b>0。验证：取 k=-1，b=1，直线 y=-x+1 与 x 轴交于 (1,0)、与 y 轴交于 (0,1)，在 x<0 时 y>0（第二象限），在 0<x<1 时 y>0（第一象限），在 x>1 时 y<0（第四象限），确不经过第三象限。故选B。","options":["k>0,\\ b>0","k<0,\\ b>0","k<0,\\ b<0","k>0,\\ b<0"],"difficulty":1,"tags":["数形结合","一次函数"]},{"id":"m-exa-xuanze-tiankong-q6","type":"short","stem":"请写出解答选择题时常用的三种速解技巧，并各配一个适合该技巧的题目情境。","answer":"（1）特值法：适用于「下列结论一定成立」类的代数恒等判断以及取值范围判断，如已知 $m<n<0$ 判断各不等式是否成立，取 $m=-2$、$n=-1$ 代入逐一检验。（2）排除法（代入验证）：适用于含参方程、函数图象判定、几何图形判定，如由「开口向下」直接排除 $a>0$ 的选项，再把剩余选项代回条件检验。（3）数形结合法：适用于一次函数、反比例函数、二次函数的图象性质与位置关系，如由图象经过的象限反推 $k$、$b$ 的符号，或由抛物线过 $(-1,0)$、$(3,0)$ 直接读出对称轴 $x=1$。此外特殊位置法适用于动点最值问题，代入端点或中点快速预判答案。","explain":"本题为方法归纳题，评分看三点：技巧名称是否规范、是否给出具体题目情境、情境与技巧是否匹配。判断匹配是否合理的标准是「该技巧确实能减少本题的运算量或思考量」：例如特值法在「一定成立」型判断中最有效，因为只需代入检验而不必证明；数形结合法在图象性质题中最有效，因为图形把抽象关系直观化了。若只列名称不给情境，或给出的情境与技巧并不契合（如把特值法用于纯几何证明题），则不能得分。","difficulty":2,"tags":["速解技巧","方法总结"],"rubric":["写出三种及以上速解技巧，名称规范（特值法、排除法、数形结合法、特殊位置法等）","每种技巧都配有具体的题目情境，而不是只给抽象定义","情境与技巧之间匹配合理，说明该技巧为何适用于该情境","表述简洁清晰，使用了规范的数学语言"]},{"id":"m-exa-xuanze-tiankong-z1","type":"choice","stem":"若 0<x<1，则 x、x²、(1)/(x) 的大小关系是（　）","answer":"A","explain":"取满足 0<x<1 的特值 x=12，则 x²=14，(1)/(x)=2，比较得 14<12<2，即 x²<x<(1)/(x)。再取 x=13 复验：x²=19<13<3=(1)/(x)，结论一致。一般地，0<x<1 时平方使数变小、取倒数使数变大。故选 A。","options":["x²<x<(1)/(x)","x<x²<(1)/(x)","(1)/(x)<x<x²","x²<(1)/(x)<x"],"difficulty":2,"tags":["特值法","实数大小比较"]},{"id":"m-exa-xuanze-tiankong-z2","type":"short","stem":"已知一个直角三角形的两条边长分别为 3 和 4，第三条边长为多少？请分类讨论并写出完整过程。","answer":"第三条边长为 5 或 $\\sqrt{7}$","explain":"题目没有说明 3 和 4 是直角边还是斜边，必须分两种情况讨论。情况一：3 和 4 都是直角边，则第三条边（斜边）为 √(3²+4²)=√(25)=5。情况二：长度为 4 的边是斜边（因 4>3，斜边不可能是 3），则第三条边为直角边，长为 √(4²-3²)=√(16-9)=√(7)。检验：3+4>5 且 3+√(7)>4，两组三边都能构成三角形；两种情况都符合题意，故答案必须写全。","difficulty":3,"tags":["勾股定理","分类讨论","填空题规范"],"rubric":["指出题目未明确直角边与斜边，需分两种情况讨论","求出 3、4 均为直角边时第三边为 5","求出 4 为斜边时第三边为 √(7)，两个答案写全"]}]},{"id":"m-exa-jihe-yazhou","title":"几何压轴题的常见模型","subtitle":"中考 · 压轴突破","grade":"all","tags":["中考应试","压轴突破"],"blocks":[{"type":"note","title":"教材章节","text":"中考 · 压轴突破"},{"type":"note","title":"一句话概述","text":"归纳手拉手、一线三等角、隐圆、将军饮马等模型，让几何压轴题有图可认。"},{"type":"h","text":"核心概念"},{"type":"p","text":"几何大题的分值位置（官方口径）：据广州市教育局2025年12月5日印发的《2027—2029年广州市初中学业水平考试录取计分科目考试实施方案》，数学满分150分、时长120分钟，客观题合计64分、占全卷42.7%，其余分数落在解答题上；方案强调优化分值结构后「解答题的思维过程评价更为充分」。现行（2024—2026年）卷为选择10题共30分、填空6题共18分、解答9题共72分，几何既渗透在客观题中（如中点四边形、圆上动点最值），也构成中档解答题的证明题与最后一题的压轴骨架。几何综合题长期占据最后一题的位置，是过程分给得最细、也最能拉开档次的题。来源：广州市教育局官网政策解读（2025年12月）。"},{"type":"p","text":"手拉手模型（共顶点旋转全等）：识别特征：两个等腰三角形（或等边三角形、正方形）共用一个顶点，且顶角相等，通常还会有一条边相接。结论：由顶角相等推得夹角相等，配合两组邻边相等，用边角边判定全等（或旋转相似）。经典结论是两个三角形全等、对应边相等、对应角相等，且两条对应边的夹角等于原顶角。凡见到「共顶点、等线段、顶角相等」就该想到它。"},{"type":"p","text":"一线三等角模型：识别特征：一条直线上依次出现三个相等的角（常见为直角），且两端连线构成三角形；图形中常伴有正方形、等腰直角三角形或矩形。结论：两端的小三角形相似，可用对应边成比例求线段长。它是「正方形中的垂直」「坐标系中的直角」类问题的通用工具。"},{"type":"p","text":"隐圆模型（动点轨迹为圆）：识别特征有四类：一动点到定点的距离恒等于定长；一动点对两定点的张角恒定；动点处出现直角（直角所对的是定线段）；四点共圆。结论：动点轨迹是一段圆弧或整圆，求最值时常配合「一箭穿心」（最小值与最大值出现在圆心与定点连线的两个方向）。据南方都市报2026年7月对广州中考数学的专家点评，2026年广州卷第25题在双翻折背景下用「双圆轨迹主从联动」确定动点位置，第16题借助瓜豆原理确定动点轨迹，都属这一模型。"},{"type":"p","text":"将军饮马与最短路径模型：识别特征：两个定点加一个在定直线上运动的动点，求 PA+PB 的最小值（或周长最小值）。作法：作其中一个定点关于动点所在直线的对称点，连接该对称点与另一个定点，线段与直线的交点即为所求动点位置，最小值为该线段的长。若动点在角的两边或两条直线上，则需作两次对称。"},{"type":"p","text":"中点四边形与中位线模型：识别特征：题目给出四边形的各边中点并要求判断所得四边形的形状或面积。结论：任意四边形的中点四边形都是平行四边形；当原四边形对角线相等时为菱形，对角线垂直时为矩形，对角线既相等又垂直时为正方形；中点四边形的面积恒为原四边形面积的一半。"},{"type":"p","text":"折叠（翻折）与旋转模型：识别特征：出现折痕、对应点、重合的角或线段。核心性质：翻折产生全等，对应边相等、对应角相等；折痕是对应点连线的垂直平分线。作辅助线时优先连接对应点或延长对应边，利用等角构造相似。"},{"type":"p","text":"相似的基本结构：A字型、X字型与母子型：识别特征：平行线截三角形得到A字型（共角共边）或X字型（对顶角）；直角三角形斜边上的高构成母子型（三个三角形两两相似）。用法：见到平行线立刻找相似比，见到直角三角形斜边上的高立刻找射影关系，这两类结构在压轴题中出现的频率极高。"},{"type":"note","title":"中考考法","text":"三秒认模型并做标记\n读题时用记号笔在图上圈出三类信号：共顶点等线段（手拉手）、直线上的三个等角（一线三等角）、直角或定长动点（隐圆）。先写「本题属某模型」再动笔，证明方向基本确定一半。"},{"type":"note","title":"中考考法","text":"辅助线的三个固定动作\n见切点连半径，见中点连中位线或倍长中线，见平行找相似三角形。每道几何题只先尝试这三个动作；都不奏效时再建坐标系，把线段、垂直、平行全部转成坐标运算。"},{"type":"note","title":"中考考法","text":"压轴三问的分段书写\n第一问的全等或相似证明独立写完整，注明判定依据；第二问把辅助线作法、关键比例式写出，即使结果算不出也保留；第三问写设元、关系式与特殊情形，争取有效步骤分，不留整页空白。"},{"type":"note","title":"中考考法","text":"相似结论的比例换算\n得到相似后先写对应边的比例式再代数，周长用相似比 k、面积用 k²；求线段时优先找含已知两边的比例，避免绕证第二次全等。算完用「长边对长边」核对对应关系。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["勾股定理","直角三角形两直角边为 a、b，斜边为 c。","求线段长时若能用两条已知边构成直角三角形，就不要绕道相似；作垂线构造直角三角形是几何压轴题最常用的辅助线动作。"],["相似三角形的面积比","k 为两相似三角形的相似比（对应边之比）。","周长比等于 k，面积比等于 k²，两者不可混淆，是压轴题中最常见的低级失分点。"],["中点坐标公式","A(x₁,y₁)、B(x₂,y₂) 的中点的坐标。","几何题一旦建立坐标系，中点、平行、垂直都能转化为代数运算，是「几何代数化」的入口。"],["两点间的距离公式","A(x₁,y₁)、B(x₂,y₂) 两点间的距离。","在坐标系中求线段长、验证等腰或直角关系时使用；先化简再开方，避免带着根号做后续运算。"],["切线长定理","过圆外一点 P 作圆的两条切线，切点为 A、B，则两条切线长相等，且 PO 平分 ∠ APB。","切线问题还要记住：切线垂直于过切点的半径；见到切线就先连半径，这是固定的辅助线动作。"],["圆上动点最值（一箭穿心）","P 为圆外（或圆内）定点，圆半径为 r，圆心为 O。","即定点到圆上各点距离的最小、最大值，出现在圆心与定点的连线上。2026年广州卷第9题即用此法秒解。"]]},{"type":"note","title":"例题","text":"如图，O 的半径为3，点 A 在圆外且 OA=5，点 P 是 O 上的一动点。求线段 AP 长度的最大值与最小值。"},{"type":"figure","figure":{"id":"fig-m-exa-jihe-1","title":"隐圆一箭穿心模型","caption":"直线 OA 穿过圆心，P 运动到与 A 共线时取得最值：最小 = OA − r = 2，最大 = OA + r = 8","view":"square","alt":"圆 O 半径 3，圆外一点 A 距圆心 5，直线 OA 穿过圆心，与圆交于最近点 P1 与最远点 P2，标注 AP 最小为 2、最大为 8","prims":[{"t":"circle","cx":38,"cy":46,"r":22.2,"tone":"main"},{"t":"line","x1":15.8,"y1":46,"x2":75,"y2":46,"tone":"muted"},{"t":"text","x":38,"y":35,"text":"r = 3","size":3.4,"tone":"muted","anchor":"middle"},{"t":"dot","x":38,"y":46,"label":"O","labelDy":-4},{"t":"dot","x":75,"y":46,"label":"A","labelDy":-4},{"t":"dot","x":60.2,"y":46,"label":"P1","labelDy":5,"tone":"accent"},{"t":"dot","x":15.8,"y":46,"label":"P2","labelDy":5},{"t":"line","x1":60.2,"y1":46,"x2":60.2,"y2":34,"dashed":true,"tone":"muted"},{"t":"line","x1":75,"y1":46,"x2":75,"y2":34,"dashed":true,"tone":"muted"},{"t":"arrow","x1":60.2,"y1":31,"x2":75,"y2":31,"both":true,"tone":"accent"},{"t":"text","x":67.6,"y":26,"text":"最小 2","size":3.4,"tone":"accent","anchor":"middle"},{"t":"line","x1":15.8,"y1":46,"x2":15.8,"y2":72,"dashed":true,"tone":"muted"},{"t":"line","x1":75,"y1":46,"x2":75,"y2":72,"dashed":true,"tone":"muted"},{"t":"arrow","x1":15.8,"y1":72,"x2":75,"y2":72,"both":true},{"t":"text","x":45.4,"y":78,"text":"最大 8","size":3.4,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["识别模型：P 在定圆上运动，A 为圆外定点，求 AP 的取值范围，属于隐圆中的「一箭穿心」模型。","取 P 落在直线 OA 上的两个特殊位置：一个在 O 与 A 之间，另一个在 O 的远离 A 的一侧。","当 P 位于线段 OA 上时，AP=OA-OP=5-3=2，这是最小值。","当 P 位于射线 AO 上且在 O 的另一侧时，AP=OA+OP=5+3=8，这是最大值。","验证：对圆上任意点 P，由三角形三边关系 |OA-OP|≤ AP≤ OA+OP，即 2≤ AP≤ 8，两个端点值均可取到。"]},{"type":"p","text":"答案：AP 的最小值为2，最大值为8。"},{"type":"note","title":"方法小结","text":"凡遇到「定圆上的动点到定点（或定直线）的距离」问题，先画出圆心与该定点的连线，最值一定出现在这条线与圆的交点处。"},{"type":"note","title":"例题","text":"在边长为4的正方形 ABCD 中，点 E 是边 BC 的中点，点 P 是对角线 BD 上的一个动点。求 PE+PC 的最小值。"},{"type":"figure","figure":{"id":"fig-m-exa-jihe-yazhou-e1","title":"正方形对角线上的动点：把折线拉直","caption":"P 在对角线 BD 上动：C 关于 BD 的对称点正是 A，于是 PE+PC=PE+PA，最小值就是线段 AE 的长","view":"square","alt":"正方形 ABCD，对角线 BD 画成虚线；E 是边 BC 的中点，线段 AE 与对角线 BD 相交于点 P；另画出虚线 PC，并标出 BE 与 EC 长度相等的记号。","prims":[{"t":"poly","points":[[22,18],[70,18],[70,66],[22,66]],"closed":true},{"t":"line","x1":70,"y1":18,"x2":22,"y2":66,"tone":"muted","dashed":true},{"t":"line","x1":22,"y1":18,"x2":70,"y2":42,"tone":"accent"},{"t":"line","x1":54,"y1":34,"x2":70,"y2":66,"tone":"accent","dashed":true},{"t":"line","x1":71.5,"y1":30,"x2":68.5,"y2":30,"tone":"ok"},{"t":"line","x1":71.5,"y1":54,"x2":68.5,"y2":54,"tone":"ok"},{"t":"dot","x":22,"y":18,"label":"A","labelDx":-5.4,"labelDy":-2.8},{"t":"dot","x":70,"y":18,"label":"B","labelDx":2.6,"labelDy":-2.8},{"t":"dot","x":70,"y":66,"label":"C","labelDx":2.6,"labelDy":2.6},{"t":"dot","x":22,"y":66,"label":"D","labelDx":-5.4,"labelDy":2.6},{"t":"dot","x":70,"y":42,"label":"E","labelDx":2.6,"labelDy":-1.4},{"t":"dot","x":54,"y":34,"label":"P","labelDx":-1.4,"labelDy":-3.2},{"t":"text","x":58,"y":30,"text":"PC = PA","anchor":"start","size":3.6,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["识别模型：两个定点 E、C 加一个在定直线 BD 上运动的动点 P，求线段和最小，属于将军饮马模型。","关键观察：C 关于对角线 BD 的对称点正是 A（正方形的对称性），因为 BD 是正方形的对称轴。","由对称性得 PC=PA，于是 PE+PC=PE+PA。","由「两点之间线段最短」，PE+PA≥ AE，当且仅当 P 落在 AE 与 BD 的交点上时取等号。","建立坐标系计算：取 A(0,0)、B(4,0)、C(4,4)，则 E(4,2)，故 AE=√((4-0)²+(2-0)²)=√(16+4)=√(20)=25。","结论：PE+PC 的最小值为 25。"]},{"type":"p","text":"答案：PE+PC 的最小值为 25。"},{"type":"note","title":"方法小结","text":"正方形中对角线是天然的对称轴，遇到「对角线上的动点 + 两定点距离和」几乎一定是作对称后转化为直线距离。"},{"type":"note","title":"例题","text":"矩形 ABCD 中，AB=6，BC=8，点 P 是平面内满足 ∠ APB=90^° 的一动点。求点 P 到直线 CD 距离的最大值。"},{"type":"figure","figure":{"id":"fig-m-exa-jihe-yazhou-e2","title":"定弦定角：∠APB=90° 时 P 在以 AB 为直径的圆上","caption":"AB=6、BC=8 的矩形中，满足 ∠APB=90° 的点 P 都在以 AB 为直径的圆上；P 到直线 CD 的距离最大为 8-3=5","view":"square","alt":"矩形 ABCD，AB 上以 AB 为直径画了一个圆，圆上交于矩形内的一点 P 与 A、B 连成直角；圆心 O 到 P 画有虚线，直线 CD 在 AB 另一侧且与 AB 平行。","prims":[{"t":"poly","points":[[24,64],[64,64],[64,11],[24,11]],"closed":true},{"t":"circle","cx":44,"cy":64,"r":20,"tone":"main"},{"t":"line","x1":44,"y1":44,"x2":24,"y2":64,"tone":"accent"},{"t":"line","x1":44,"y1":44,"x2":64,"y2":64,"tone":"accent"},{"t":"line","x1":44,"y1":64,"x2":44,"y2":44,"tone":"muted","dashed":true},{"t":"line","x1":41.17,"y1":46.83,"x2":44,"y2":49.66,"tone":"muted"},{"t":"line","x1":44,"y1":49.66,"x2":46.83,"y2":46.83,"tone":"muted"},{"t":"line","x1":32.8,"y1":62.5,"x2":32.8,"y2":65.5,"tone":"ok"},{"t":"line","x1":35.2,"y1":62.5,"x2":35.2,"y2":65.5,"tone":"ok"},{"t":"line","x1":52.8,"y1":62.5,"x2":52.8,"y2":65.5,"tone":"ok"},{"t":"line","x1":55.2,"y1":62.5,"x2":55.2,"y2":65.5,"tone":"ok"},{"t":"dot","x":24,"y":64,"label":"A","labelDx":-5.4,"labelDy":2.6},{"t":"dot","x":64,"y":64,"label":"B","labelDx":2.6,"labelDy":2.6},{"t":"dot","x":64,"y":11,"label":"C","labelDx":2.6,"labelDy":-2.8},{"t":"dot","x":24,"y":11,"label":"D","labelDx":-5.4,"labelDy":-2.8},{"t":"dot","x":44,"y":64,"label":"O","labelDx":-5,"labelDy":3.2},{"t":"dot","x":44,"y":44,"label":"P","labelDx":2.6,"labelDy":-1.4},{"t":"text","x":28,"y":78,"text":"AB = 6","anchor":"middle","size":3.6,"tone":"muted"},{"t":"text","x":70,"y":40,"text":"BC = 8","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":70,"y":52,"text":"OP = 3","anchor":"start","size":3.6,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["识别模型：动点 P 对定线段 AB 的张角恒为 90^°，属于「定弦定角」的隐圆模型。","由「直径所对的圆周角是直角」的逆定理，P 在以 AB 为直径的圆上（不含 A、B 两点）。","取坐标：A(0,0)、B(6,0)，则圆心为 AB 的中点 O(3,0)，半径 r=3。","直线 CD 的方程为 y=8（因为矩形中 CD∥ AB 且与 AB 的距离为8）。","点 P 的纵坐标满足 y≤ r=3，当 P 位于 O 正上方即 (3,3) 时取到最大值。","故点 P 到直线 CD 的最大距离为 8-3=5。"]},{"type":"p","text":"答案：最大距离为5。"},{"type":"note","title":"方法小结","text":"「动点处出现直角」是隐圆最常考的触发条件，立即想到「以定线段为直径作圆」，轨迹一确定，最值就变成了定点到圆上的点的距离问题。"},{"type":"note","title":"例题","text":"如图，在正方形 ABCD 中，边长为 4，点 E 在边 BC 上，BE=1，过点 E 作 EF⊥ AE，交边 CD 于点 F。求线段 CF 的长。"},{"type":"figure","figure":{"id":"fig-m-exa-jihe-2","title":"正方形中的一线三等角","caption":"∠BAE 与 ∠CEF 同为 ∠AEB 的余角，故 △ABE ∽ △ECF，AB:EC = BE:CF，CF = 3/4","view":"square","alt":"正方形 ABCD 边长 4，边 BC 上点 E 满足 BE = 1，连接 AE，过 E 作 AE 的垂线交边 CD 于点 F，标注 BE = 1、EC = 3、CF = 3/4","prims":[{"t":"poly","points":[[16,20],[16,64],[60,64],[60,20]],"closed":true},{"t":"line","x1":16,"y1":20,"x2":27,"y2":64},{"t":"line","x1":27,"y1":64,"x2":60,"y2":55.75,"tone":"accent","width":1.5},{"t":"angle","x":27,"y":64,"from":256,"to":346,"right":true,"tone":"accent"},{"t":"angle","x":16,"y":64,"from":270,"to":360,"right":true,"tone":"muted"},{"t":"angle","x":60,"y":64,"from":180,"to":270,"right":true,"tone":"muted"},{"t":"dot","x":16,"y":20,"label":"A","labelDx":-4,"labelDy":-2},{"t":"dot","x":16,"y":64,"label":"B","labelDx":-4,"labelDy":4},{"t":"dot","x":60,"y":64,"label":"C","labelDx":4,"labelDy":4},{"t":"dot","x":60,"y":20,"label":"D","labelDx":4,"labelDy":-2},{"t":"dot","x":27,"y":64,"label":"E","labelDy":5,"tone":"accent"},{"t":"dot","x":60,"y":55.75,"label":"F","labelDx":5,"tone":"accent"},{"t":"text","x":21.5,"y":71,"text":"BE = 1","size":3.2,"anchor":"middle"},{"t":"text","x":43.5,"y":71,"text":"EC = 3","size":3.2,"anchor":"middle"},{"t":"text","x":65,"y":59,"text":"CF = 3/4","size":3.2,"tone":"accent"},{"t":"text","x":12,"y":44,"text":"4","size":3.2,"anchor":"end"}]}},{"type":"list","title":"解题步骤","items":["怎么想到：直线 BC 上依次出现 ∠ B=90^°、∠ AEF=90^°、∠ C=90^° 三个直角，是典型的一线三等角模型，应立即找两端的小三角形相似。","在三角形 ABE 中，∠ BAE+∠ AEB=90^°；又 ∠ AEF=90^°，故 ∠ AEB+∠ CEF=90^°，由同角的余角相等得 ∠ BAE=∠ CEF。","又 ∠ B=∠ C=90^°，所以 △ ABE△ ECF（两角分别相等）。","写比例式 (AB)/(EC)=(BE)/(CF)。由 EC=BC-BE=4-1=3，代入得 (4)/(3)=(1)/(CF)，解得 CF=(3)/(4)。检验：两三角形长边对应长边（AE 对应 EF），对应关系无误，CF=34<4，点 F 确实落在边 CD 上。"]},{"type":"p","text":"答案：线段 CF 的长为 (3)/(4)"},{"type":"note","title":"方法小结","text":"一线三等角中「同角的余角相等」是得到第二组等角的关键；列比例前先把对应顶点按顺序写好（Ato E，Bto C，Eto F），可避免对应边错位。"},{"type":"note","title":"例题","text":"如图，在 △ ABC 中，∠ ACB=90^°，CD⊥ AB 于点 D，AC=6，BC=8。求线段 AB、CD、AD、BD 的长。"},{"type":"figure","figure":{"id":"fig-m-exa-jihe-3","title":"直角三角形的斜边高（母子型）","caption":"等面积求高 CD = 6×8÷10 = 4.8，射影定理 AD = 3.6、BD = 6.4，且 AD + BD = AB = 10","view":"square","alt":"直角三角形 ABC，直角在 C，斜边 AB 上的高 CD 垂足为 D，标注 AC = 6、BC = 8、AB = 10、AD = 3.6、BD = 6.4、CD = 4.8","prims":[{"t":"poly","points":[[14,41.2],[70,41.2],[34.2,68.1]],"closed":true},{"t":"line","x1":34.2,"y1":41.2,"x2":34.2,"y2":68.1,"tone":"accent","width":1.5},{"t":"angle","x":34.2,"y":68.1,"from":233.1,"to":323.1,"right":true,"tone":"muted"},{"t":"angle","x":34.2,"y":41.2,"from":90,"to":180,"right":true,"tone":"accent"},{"t":"dot","x":14,"y":41.2,"label":"A","labelDx":-4,"labelDy":-2},{"t":"dot","x":70,"y":41.2,"label":"B","labelDx":4,"labelDy":-2},{"t":"dot","x":34.2,"y":68.1,"label":"C","labelDy":5},{"t":"dot","x":34.2,"y":41.2,"label":"D","labelDy":-4,"tone":"accent"},{"t":"text","x":18,"y":58,"text":"AC = 6","size":3.2,"anchor":"middle"},{"t":"text","x":60,"y":58,"text":"BC = 8","size":3.2,"anchor":"middle"},{"t":"text","x":24,"y":36,"text":"AD = 3.6","size":3.2,"anchor":"middle"},{"t":"text","x":52.1,"y":36,"text":"BD = 6.4","size":3.2,"anchor":"middle"},{"t":"text","x":42,"y":30,"text":"AB = 10","size":3.2,"anchor":"middle"},{"t":"text","x":37.5,"y":47,"text":"CD = 4.8","size":3.2,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["怎么想到：直角三角形斜边上有高，图中三个直角三角形两两相似，是母子型模型；先用勾股定理求斜边，再用等面积法求斜边上的高，射影关系求两段。","由勾股定理：AB=√(AC²+BC²)=√(36+64)=10。","由等面积法，S_(△ ABC)=12 AC· BC=12 AB· CD，故 CD=(6×8)/(10)=(24)/(5)=4.8。","由母子型相似的射影结论 AC²=AD· AB，得 AD=(AC²)/(AB)=(36)/(10)=(18)/(5)=3.6；同理 BD=(BC²)/(AB)=(64)/(10)=(32)/(5)=6.4。检验：AD+BD=3.6+6.4=10=AB，且 AD²+CD²=3.6²+4.8²=36=AC²，各量全部自洽。"]},{"type":"p","text":"答案：AB=10，CD=(24)/(5)（4.8），AD=(18)/(5)（3.6），BD=(32)/(5)（6.4）"},{"type":"note","title":"方法小结","text":"母子型三句话：斜边上的高用等面积法求，直角边的平方等于它在斜边上的射影乘斜边，两段相加必须等于斜边——最后一步是最省事的检验。"},{"type":"list","title":"易错点","items":["分类讨论遗漏：等腰三角形的顶角位置、直角所在顶点、动点在射线上还是在直线上，都会产生多个解，只写一种情况必然扣分。","辅助线想不到就先空着：几何压轴题第一问通常只需简单推理或直接使用已知条件，整体放弃等于白白丢分。","混淆相似比与面积比：把面积比当作相似比，或把周长比与面积比弄反，是几何大题中最常见的计算性失分。","折叠问题中忘记对应关系：翻折后哪条边对应哪条边、哪个角等于哪个角必须标清，凭感觉作图会导致相似关系用错。","作对称时对称轴选错：将军饮马模型中必须作定点关于动点所在直线的对称点，作错方向后得到的交点位置与最小值全错。","证明过程缺依据：写「因为 $AB=AC$，所以 $\\angle B=\\angle C$」却不写「等边对等角」或指出所在三角形，会被扣过程分。"]},{"type":"list","title":"解题方法","items":["先认模型再动手：拿到几何综合题先扫一遍图形，判断是否出现共顶点等线段（手拉手）、一线三等角、动点定长或定角（隐圆）、两定一动求最小（将军饮马），模型一旦识别，思路就基本确定。","辅助线的三个固定动作：见到切点连半径，见到中点想中位线或倍长中线，见到平行想相似（A字型或X字型）。","几何代数化：当纯几何推理受阻时，果断建立坐标系，把线段长、面积、垂直、平行都化为坐标运算，尤其适合求长度与最值。","逆向分析：从结论出发反推需要什么条件，再看已知能提供什么，缺什么就补什么辅助线，这是压轴题最有效的思考路径。","过程书写到位：每步推理注明依据（全等或相似的判定、定理名称），图形关键位置标出对应关系，过程分才拿得全。","分段得分：压轴题的三问通常独立给分，第一问务必写完整，第二问写出关键结论与辅助线往往也能得步骤分。"]}],"questions":[{"id":"m-exa-jihe-yazhou-q1","type":"choice","stem":"下列图形特征中，最典型地指向「手拉手模型」的是（　）","answer":"B","explain":"手拉手模型的识别特征是「共顶点、等线段、顶角相等」：两个等腰三角形（或等边三角形、正方形）共用一个顶点且顶角相等，配合两组邻边相等，可用边角边（或旋转相似）得到全等。A描述的是一线三等角模型，C描述的是四点共圆（隐圆的一种），D描述的是梯形中位线定理，均不属于手拉手模型。","options":["一条直线上依次出现三个相等的角","两个顶角相等的等腰三角形共用一个顶点","四边形四个顶点在同一个圆上","梯形两腰中点的连线平行于底边"],"difficulty":1,"tags":["手拉手模型","模型识别"]},{"id":"m-exa-jihe-yazhou-q2","type":"choice","stem":"直线 l 的同侧有两点 A、B，点 P 在直线 l 上运动。要使 PA+PB 最小，正确的作法是（　）","answer":"A","explain":"这是将军饮马模型。作 A 关于 l 的对称点 A'，则 PA=PA'，于是 PA+PB=PA'+PB≥ A'B，当 P 为 A'B 与 l 的交点时取等号，最小值为 A'B。B的作法得到的是到 A、B 距离相等而非距离和最小的点；C、D都不能保证距离和最小。","options":["作点 A 关于直线 l 的对称点 A'，连接 A'B 交 l 于点 P","作线段 AB 的垂直平分线交 l 于点 P","过点 A 作直线 l 的垂线，垂足即为 P","连接 AB 并延长交 l 于点 P"],"difficulty":2,"tags":["将军饮马","最短路径"],"figure":{"id":"fig-m-exa-jihe-yazhou-q2","title":"同侧两点到定直线上一点的距离和","caption":"直线 l 同侧有 A、B：作 A 关于 l 的对称点 A′，连接 A′B 交 l 于 P，此时 PA+PB 最小（等于 A′B）","view":"wide","alt":"水平直线 l 的上方有两点 A 与 B；点 A 关于 l 的对称点 A′ 在 l 的下方，线段 A′B 与 l 相交于点 P，图中画出了 AP、PB 与 A′P。","prims":[{"t":"line","x1":6,"y1":58,"x2":94,"y2":58,"width":0.8},{"t":"line","x1":20,"y1":30,"x2":20,"y2":86,"tone":"muted","dashed":true},{"t":"line","x1":20,"y1":30,"x2":40.5,"y2":58,"tone":"accent"},{"t":"line","x1":40.5,"y1":58,"x2":58,"y2":34,"tone":"accent"},{"t":"line","x1":20,"y1":86,"x2":40.5,"y2":58,"tone":"accent","dashed":true},{"t":"line","x1":20,"y1":54.5,"x2":23.5,"y2":54.5,"tone":"muted"},{"t":"line","x1":23.5,"y1":54.5,"x2":23.5,"y2":58,"tone":"muted"},{"t":"line","x1":21.5,"y1":44,"x2":18.5,"y2":44,"tone":"ok"},{"t":"line","x1":21.5,"y1":72,"x2":18.5,"y2":72,"tone":"ok"},{"t":"text","x":94,"y":52,"text":"l","anchor":"end","size":3.6,"tone":"muted"},{"t":"dot","x":20,"y":30,"label":"A","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":58,"y":34,"label":"B","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":40.5,"y":58,"label":"P","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":20,"y":86,"label":"A′","labelDx":-6,"labelDy":2.6},{"t":"text","x":60,"y":44,"text":"PA + PB 最小","anchor":"start","size":3.6,"tone":"accent"}]}},{"id":"m-exa-jihe-yazhou-q3","type":"fill","stem":"顺次连接菱形各边中点所得的四边形是____形。","answer":"矩|矩形","explain":"任意四边形的中点四边形都是平行四边形：连接对角线后，由三角形中位线定理可证四边分别平行且等于原四边形对角线的一半。菱形的对角线互相垂直，故中点四边形的邻边互相垂直，所以它是矩形。可记忆为：原四边形对角线相等则中点四边形为菱形，对角线垂直则为矩形，两者兼具则为正方形。","difficulty":2,"tags":["中点四边形","中位线"]},{"id":"m-exa-jihe-yazhou-q4","type":"fill","stem":"在 △ ABC 中，AC=3，点 P 是平面内满足 CP=2 的动点（P 不与 A 重合），则线段 AP 的最小值为____。","answer":"1","explain":"由 CP=2 知点 P 在以 C 为圆心、2为半径的圆上，A 是圆外定点（AC=3>2），属隐圆中的「一箭穿心」模型。对圆上任意点 P，由三角形三边关系 |AC-CP|≤ AP≤ AC+CP，即 1≤ AP≤5。当 P 落在线段 AC 上时 AP=AC-CP=3-2=1 取到最小值。","difficulty":2,"tags":["隐圆","最值"],"figure":{"id":"fig-m-exa-jihe-yazhou-q4","title":"一箭穿心：圆上的点到圆外定点的最短距离","caption":"CP=2 的点 P 都在以 C 为圆心、2 为半径的圆上；A 在圆外且 AC=3，当 P 落在 AC 上时 AP 最小，最小值为 3-2=1","view":"square","alt":"以 C 为圆心、2 为半径的圆，圆心 C 与圆外一点 A 连成线段 AC；线段 AC 与圆相交于点 P，图中标出 CP 与 AC 的长度。","prims":[{"t":"circle","cx":40,"cy":50,"r":26,"tone":"main"},{"t":"line","x1":40,"y1":50,"x2":79,"y2":50,"tone":"accent"},{"t":"line","x1":79,"y1":50,"x2":66,"y2":50,"tone":"danger","width":1.2},{"t":"line","x1":52,"y1":16,"x2":79,"y2":50,"tone":"muted","width":0.7},{"t":"line","x1":52,"y1":16,"x2":40,"y2":50,"tone":"muted","width":0.7},{"t":"dot","x":52,"y":16,"label":"B","labelDx":-1.6,"labelDy":-3.4},{"t":"line","x1":53,"y1":48.5,"x2":53,"y2":51.5,"tone":"ok"},{"t":"text","x":53,"y":44,"text":"CP = 2","anchor":"middle","size":3.6,"tone":"muted"},{"t":"text","x":71,"y":44,"text":"AC = 3","anchor":"start","size":3.6,"tone":"muted"},{"t":"dot","x":40,"y":50,"label":"C","labelDx":-5.4,"labelDy":-2.8},{"t":"dot","x":79,"y":50,"label":"A","labelDx":-2,"labelDy":-3.6},{"t":"dot","x":66,"y":50,"label":"P","labelDx":-1.6,"labelDy":3.2},{"t":"text","x":66,"y":62,"text":"AP 最小 = ?","anchor":"middle","size":3.6,"tone":"danger"}]}},{"id":"m-exa-jihe-yazhou-q5","type":"short","stem":"在 △ ABC 中，AB=AC，∠ BAC=90^°，点 D 是边 BC 上一点（不与 B、C 重合）。将线段 AD 绕点 A 逆时针旋转 90^° 得到线段 AE，连接 CE。求证：BD=CE，并求 ∠ BCE 的度数。","answer":"由旋转得 $AD=AE$，$\\angle DAE=90^\\circ$。因为 $\\angle BAC=90^\\circ$，所以 $\\angle BAD=90^\\circ-\\angle DAC$，$\\angle CAE=\\angle DAE-\\angle DAC=90^\\circ-\\angle DAC$，故 $\\angle BAD=\\angle CAE$。在 $\\triangle BAD$ 与 $\\triangle CAE$ 中，$AB=AC$，$\\angle BAD=\\angle CAE$，$AD=AE$，所以 $\\triangle BAD\\cong\\triangle CAE$（边角边），从而 $BD=CE$。又由全等得 $\\angle ACE=\\angle ABD$；因 $AB=AC$ 且 $\\angle BAC=90^\\circ$，故 $\\angle ABC=\\angle ACB=45^\\circ$，所以 $\\angle ACE=45^\\circ$，于是 $\\angle BCE=\\angle BCA+\\angle ACE=45^\\circ+45^\\circ=90^\\circ$。","explain":"本题考查手拉手（共顶点旋转全等）模型。识别特征在题中已经齐备：AB 与 AC、AD 与 AE 分别是两组共顶点的等线段，且顶角都是 90^°。解题的核心一步是用「同角的余角相等」推出 ∠ BAD=∠ CAE——有了这个角相等，加上两组邻边相等，边角边判定即可成立。不少同学会误以为是旋转直接给出夹角相等，其实必须通过 ∠ BAC=∠ DAE=90^° 减去同一个角 ∠ DAC 来论证，这一步是评分的关键依据。第二问求 ∠ BCE 时，要把这个角拆成 ∠ BCA 与 ∠ ACE 两部分之和，其中 ∠ BCA=45^° 来自等腰直角三角形，∠ ACE=45^° 来自全等的对应角关系。","difficulty":3,"tags":["手拉手模型","旋转","全等三角形"],"rubric":["由旋转正确得出 AD=AE 与 ∠ DAE=90^°","利用同角的余角关系推出 ∠ BAD=∠ CAE（这是本题的核心步骤）","明确写出边角边（SAS）的判定依据并得到 △ BAD≌△ CAE","由全等得出 BD=CE 与 ∠ ACE=∠ ABD","求出等腰直角三角形底角为 45^°，进而得出 ∠ BCE=90^°","推理链条完整，每步都有依据，图形标注清晰"],"figure":{"id":"fig-m-exa-jihe-yazhou-q5","title":"手拉手模型：共顶点旋转的全等三角形","caption":"把 AD 绕 A 逆时针转 90° 得 AE（AD=AE 且 AD 垂直于 AE）；由 ∠BAD=∠CAE 得 △BAD≌△CAE，所以 BD=CE、∠BCE=90°","view":"square","alt":"等腰直角三角形 ABC，顶点 A 处是直角；D 是斜边 BC 上一点，线段 AD 绕点 A 逆时针旋转 90° 得到 AE，连接 CE；图中在顶点 A 处标出两组相等的角，BD 与 CE 上画有相同的等长记号。","prims":[{"t":"poly","points":[[65,66.25],[65,33.25],[32,66.25]],"closed":true},{"t":"line","x1":65,"y1":66.25,"x2":48.5,"y2":49.75,"tone":"accent"},{"t":"line","x1":65,"y1":66.25,"x2":48.5,"y2":82.75,"tone":"accent"},{"t":"line","x1":32,"y1":66.25,"x2":48.5,"y2":82.75,"tone":"ok","width":1},{"t":"line","x1":65,"y1":61.25,"x2":60,"y2":61.25,"tone":"muted"},{"t":"line","x1":60,"y1":61.25,"x2":60,"y2":66.25,"tone":"muted"},{"t":"line","x1":59.34,"y1":60.59,"x2":53.69,"y2":66.25,"tone":"muted"},{"t":"line","x1":53.69,"y1":66.25,"x2":59.34,"y2":71.91,"tone":"muted"},{"t":"angle","x":65,"y":66.25,"from":90,"to":135,"r":11,"tone":"danger"},{"t":"angle","x":65,"y":66.25,"from":-180,"to":-135,"r":15,"tone":"danger"},{"t":"line","x1":55.69,"y1":59.06,"x2":57.81,"y2":56.94,"tone":"ok"},{"t":"line","x1":57.81,"y1":75.56,"x2":55.69,"y2":73.44,"tone":"ok"},{"t":"line","x1":58.66,"y1":41.71,"x2":56.54,"y2":39.59,"tone":"ok"},{"t":"line","x1":56.96,"y1":43.41,"x2":54.84,"y2":41.29,"tone":"ok"},{"t":"line","x1":40.46,"y1":72.59,"x2":38.34,"y2":74.71,"tone":"ok"},{"t":"line","x1":42.16,"y1":74.29,"x2":40.04,"y2":76.41,"tone":"ok"},{"t":"dot","x":65,"y":66.25,"label":"A","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":65,"y":33.25,"label":"B","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":32,"y":66.25,"label":"C","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":48.5,"y":49.75,"label":"D","labelDx":2.2,"labelDy":-2.6},{"t":"dot","x":48.5,"y":82.75,"label":"E","labelDx":2.2,"labelDy":-2.6},{"t":"text","x":66,"y":47,"text":"BD = CE","anchor":"start","size":3.6,"tone":"ok"}]}},{"id":"m-exa-jihe-yazhou-z1","type":"choice","stem":"如图，在 △ ABC 中，DE∥ BC，点 D、E 分别在边 AB、AC 上，且 AD:DB=1:2。则 △ ADE 与四边形 DBCE 的面积比为（　）","answer":"D","explain":"由 AD:DB=1:2 得 AD:AB=1:(1+2)=1:3。因 DE∥ BC，故 △ ADE△ ABC（A字型），相似比为 13，面积比为相似比的平方，即 S_(△ ADE):S_(△ ABC)=1:9。四边形 DBCE 的面积为 9-1=8 份，故所求面积比为 1:8。误选 C 是把大三角形当成了四边形；周长比才是 1:3。故选 D。","options":["1:2","1:3","1:9","1:8"],"difficulty":2,"tags":["相似三角形","A字型","面积比"],"figure":{"id":"fig-m-exa-jihe-4","title":"A 字型相似与面积比","caption":"DE∥BC，AD 占 1 份、DB 占 2 份，AD:AB = 1:3，S△ADE:S△ABC = 1:9，故与四边形 DBCE 之比为 1:8","view":"square","alt":"三角形 ABC 中，线段 DE 平行于底边 BC，把三角形分成上方的小三角形 ADE 与下方的梯形 DBCE，AB 边上 AD 段标 1、DB 段标 2","prims":[{"t":"poly","points":[[50,18],[20,66],[80,66]],"closed":true},{"t":"poly","points":[[50,18],[40,34],[60,34]],"closed":true,"tone":"accent","fill":true},{"t":"line","x1":40,"y1":34,"x2":60,"y2":34,"tone":"accent","width":1.5},{"t":"dot","x":50,"y":18,"label":"A","labelDy":-4},{"t":"dot","x":20,"y":66,"label":"B","labelDx":-4,"labelDy":4},{"t":"dot","x":80,"y":66,"label":"C","labelDx":4,"labelDy":4},{"t":"dot","x":40,"y":34,"label":"D","labelDx":-5,"tone":"accent"},{"t":"dot","x":60,"y":34,"label":"E","labelDx":5,"tone":"accent"},{"t":"text","x":41,"y":23,"text":"1","size":3.2,"tone":"muted","anchor":"middle"},{"t":"text","x":26,"y":47,"text":"2","size":3.2,"tone":"muted","anchor":"middle"},{"t":"text","x":50,"y":29,"text":"△ADE","size":3,"tone":"accent","anchor":"middle"},{"t":"text","x":50,"y":55,"text":"四边形 DBCE","size":3,"anchor":"middle"}]}},{"id":"m-exa-jihe-yazhou-z2","type":"short","stem":"如图，在矩形 ABCD 中，AB=6，BC=8，沿直线 AE 折叠（点 E 在边 BC 上），点 B 恰好落在对角线 AC 上的点 F 处。求线段 BE 的长。","answer":"线段 $BE$ 的长为 3","explain":"矩形中 ∠ B=90^°，故对角线 AC=√(AB²+BC²)=√(36+64)=10。由折叠的性质，△ ABE 与 △ AFE 重合，故 AF=AB=6，BE=FE，且 ∠ AFE=∠ B=90^°，于是 ∠ CFE=90^°，FC=AC-AF=10-6=4。设 BE=x，则 FE=x，EC=BC-BE=8-x。在直角三角形 EFC 中，由勾股定理 x²+4²=(8-x)²，展开得 x²+16=64-16x+x²，解得 x=3。检验：FE=3、EC=5，3²+4²=25=5²，直角三角形 EFC 三边成立。","difficulty":3,"tags":["折叠模型","勾股定理","矩形"],"rubric":["由勾股定理求出对角线 AC=10，并由折叠得到 AF=6、FC=4 与 ∠ CFE=90^°","设 BE=x，用折叠对应关系表示 FE=x、EC=8-x","在直角三角形 EFC 中用勾股定理列方程并解得 BE=3"],"figure":{"id":"fig-m-exa-jihe-5","title":"矩形折叠：B 落在对角线上","caption":"折叠后 AF = AB = 6，FC = 10−6 = 4，设 BE = x，直角在 F：x² + 4² = (8−x)²，解得 BE = 3","view":"square","alt":"矩形 ABCD，AB = 6，BC = 8，沿 AE 折叠后点 B 落在对角线 AC 上的 F 处，三角形 AEF 填色表示折叠后的位置，标注 AF = 6、FC = 4、BE = 3、EC = 5","prims":[{"t":"poly","points":[[16,27],[16,66],[68,66],[68,27]],"closed":true},{"t":"line","x1":16,"y1":27,"x2":68,"y2":66,"dashed":true,"tone":"muted"},{"t":"poly","points":[[16,27],[35.5,66],[47.2,50.4]],"closed":true,"tone":"accent","fill":true},{"t":"line","x1":16,"y1":27,"x2":35.5,"y2":66,"tone":"main","width":1.8},{"t":"line","x1":35.5,"y1":66,"x2":47.2,"y2":50.4,"dashed":true,"tone":"accent","width":1.5},{"t":"arrow","x1":16,"y1":66,"x2":43,"y2":52.5,"dashed":true,"tone":"muted"},{"t":"angle","x":16,"y":66,"from":270,"to":360,"right":true,"tone":"muted"},{"t":"dot","x":16,"y":27,"label":"A","labelDx":-4,"labelDy":-2},{"t":"dot","x":16,"y":66,"label":"B","labelDx":-4,"labelDy":4},{"t":"dot","x":68,"y":66,"label":"C","labelDx":4,"labelDy":4},{"t":"dot","x":68,"y":27,"label":"D","labelDx":4,"labelDy":-2},{"t":"dot","x":35.5,"y":66,"label":"E","labelDy":5,"tone":"accent"},{"t":"dot","x":47.2,"y":50.4,"label":"F","labelDx":-5,"labelDy":-2,"hollow":true,"tone":"accent"},{"t":"text","x":13,"y":46,"text":"AB = 6","size":3.2,"anchor":"end"},{"t":"text","x":34.6,"y":34.7,"text":"AF = 6","size":3.2,"tone":"accent","anchor":"middle"},{"t":"text","x":60.6,"y":54.2,"text":"FC = 4","size":3.2,"tone":"accent","anchor":"middle"},{"t":"text","x":25.75,"y":72,"text":"BE = 3","size":3.2,"tone":"accent","anchor":"middle"},{"t":"text","x":51.75,"y":72,"text":"EC = 5","size":3.2,"anchor":"middle"}]}}]},{"id":"m-exa-hanshu-yazhou","title":"函数与几何综合压轴题","subtitle":"中考 · 压轴突破","grade":"all","tags":["中考应试","压轴突破"],"blocks":[{"type":"note","title":"教材章节","text":"中考 · 压轴突破"},{"type":"note","title":"一句话概述","text":"打通二次函数与几何的连结：交点、定点、面积、存在性问题四类套路。"},{"type":"h","text":"核心概念"},{"type":"p","text":"函数大题的分值位置（官方口径）：据广州市教育局2025年12月5日印发的《2027—2029年广州市初中学业水平考试录取计分科目考试实施方案》，数学满分150分、时长120分钟，客观题合计64分、占全卷42.7%，其余分值由解答题承载；方案特别指出优化分值结构是「为了让解答题的思维过程评价更为充分」。函数综合题通常位于第24题，与第25题的几何压轴共同构成全卷的区分核心。来源：广州市教育局官网政策解读（2025年12月）。"},{"type":"p","text":"现行卷中的函数考点分布：现行（2024—2026年）卷为选择10题共30分、填空6题共18分、解答9题共72分。函数在选择、填空、解答三个层次都出现：客观题考图象平移、象限判断、含参结论判断，解答题考解析式求解、交点、面积与存在性问题，权重贯穿全卷。"},{"type":"p","text":"二次函数的三种表达式：一般式 y=ax²+bx+c 适合已知三点；顶点式 y=a(x-h)²+k 适合已知顶点或求最值；交点式 y=a(x-x₁)(x-x₂) 适合已知与 x 轴的两个交点。考场上应根据题目给的条件选择最省力的形式，尤其「已知两根」时应立即用交点式，可省去解方程组的时间。"},{"type":"p","text":"直线与抛物线的交点：把直线与抛物线的解析式联立，消去 y 得到关于 x 的一元二次方程，其解就是交点的横坐标，判别式的符号决定交点个数。含参方程还能借助根与系数的关系（韦达定理）整体处理两交点横坐标的和与积，避免求出具体的根。据南方都市报2026年7月对广州中考数学的专家点评，2026年广州卷第24题考查含参计算与对函数问题的解读能力，即属此类。"},{"type":"p","text":"恒过定点问题：当解析式中含有参数时，要判断图象是否恒过某个定点，做法是「按参数分组」：把含参数的项集中，令参数的系数为零，解出 x，再代回求 y。若得到的点坐标与参数无关，则该点就是定点。这是近年函数压轴题的高频设问，2026年广州卷第24题即考查恒过定点。"},{"type":"p","text":"面积表示与割补法：抛物线中三角形的面积常不便直接用底和高计算，标准做法是「铅垂法」：用一条竖直线截三角形，把面积表示为水平宽与铅垂高乘积的一半。当动点在抛物线上、两个定点分别在直线与坐标轴上时，铅垂高恰好等于抛物线对应的函数值与直线对应的函数值之差，从而把面积问题转化为二次函数最值问题。"},{"type":"p","text":"存在性问题与分类讨论：常见设问：抛物线上是否存在点使某三角形为等腰三角形、直角三角形、或是平行四边形的一个顶点，是否存在点使两三角形相似或面积成倍分关系。通用套路是设出点的坐标（含参数），用距离公式、斜率关系或相似比列方程，再按分类标准逐一讨论，最后检验所求点是否在题目限定的范围（如「在抛物线上」「不与某点重合」）。"},{"type":"p","text":"反比例函数与一次函数综合：核心性质是反比例函数图象关于原点中心对称，因此若一次函数图象也关于原点中心对称（即过原点），两交点关于原点对称，横坐标互为相反数。比较函数值大小的方法是数形结合：在同一坐标系中画出两图象，按交点把 x 的取值分段，逐段判断哪条曲线在上方。"},{"type":"note","title":"中考考法","text":"压轴第一问的固定得分动作\n第一问通常是求解析式或证交点：给两点用待定系数，给顶点用顶点式，证恒有交点就算判别式。要完整书写并回查系数，它是后面小问的平台，错一个系数全题连锁失分。"},{"type":"note","title":"中考考法","text":"面积与最值先搭铅垂桥\n抛物线内三角形的面积一律先用铅垂法：水平宽取两定点横坐标之差，铅垂高写为抛物线的函数值减直线的函数值；配方前先确认动点范围，最值点越界就要回端点取值。"},{"type":"note","title":"中考考法","text":"含参问题分定点与韦达两路\n证恒过定点就按参数分组、令参数系数为零；处理含参交点先联立消元，再看设问：求交点个数用判别式，求对称式用根与系数的关系，且使用前必须先说明判别式非负。"},{"type":"note","title":"中考考法","text":"存在性问题的分类与检验清单\n等腰按三边轮作底、直角按三顶点轮作直角顶点、平行四边形按对角线分类；每类设点列方程解出后，立即回代检验是否在抛物线上、是否与已知点重合，超范围的解要舍去。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["二次函数的顶点坐标","对称轴为直线 x=-(b)/(2a)。","求最值、判断增减性、确定动点位置都以此为起点；先算对称轴再看题目给定的取值范围，若范围不含对称轴则最值在端点取到。"],["交点式（两根式）","x₁、x₂ 为抛物线与 x 轴交点的横坐标。","已知两根时使用可大幅减少运算量；展开后 b=-a(x₁+x₂)，c=ax₁x₂，可用于快速判断系数的符号。"],["根与系数的关系","方程 ax²+bx+c=0（a≠0）两根满足的关系。","处理含参交点问题时可以整体代入，避开求根；使用前必须先确认 Δ≥0，否则两根可能不存在。"],["两点间的距离公式","P(x₁,y₁)、Q(x₂,y₂) 两点间的距离。","等腰三角形存在性问题中，分别写出三边长的平方再分类讨论，比开方后讨论更快且不易出错。"],["点到直线的距离","点 (x₀,y₀) 到直线 Ax+By+C=0 的距离。","适用于求抛物线上动点到定直线距离的最大值，把距离表示成关于动点横坐标的函数后配方求最值。"],["铅垂法求三角形面积","水平宽为两端点横坐标之差的绝对值，铅垂高为过动点的竖直线被三角形两定点所在直线截得的线段长。","这是抛物线中面积问题的标准工具，能把面积表示成二次函数，配方后即得最大值与对应的动点坐标。"]]},{"type":"note","title":"例题","text":"已知抛物线 y=x²-2x-3 与 x 轴交于点 A、B（A 在 B 左侧），与 y 轴交于点 C。求 △ ABC 的面积。"},{"type":"figure","figure":{"id":"fig-m-exa-hanshu-1","title":"抛物线与三角形面积","caption":"A(−1,0)、B(3,0)、C(0,−3)，AB = 4，高 = 3，S = ½×4×3 = 6","view":"wide","alt":"平面直角坐标系中的抛物线 y = x²−2x−3，开口向上，与 x 轴交于 A(−1,0) 和 B(3,0)，与 y 轴交于 C(0,−3)，三角形 ABC 以 AB 为底、高为 3，面积为 6","prims":[{"t":"arrow","x1":24,"y1":40,"x2":86,"y2":40,"tone":"muted"},{"t":"arrow","x1":46,"y1":72,"x2":46,"y2":10,"tone":"muted"},{"t":"text","x":88,"y":42,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":49,"y":13,"text":"y","size":3.4,"tone":"muted"},{"t":"curve","points":[[34,10],[37,26.5],[40,40],[43,50.5],[46,58],[49,62.5],[52,64],[55,62.5],[58,58],[61,50.5],[64,40],[67,26.5],[70,10]],"tone":"accent"},{"t":"poly","points":[[40,40],[64,40],[46,58]],"closed":true,"tone":"accent","fill":true},{"t":"line","x1":46,"y1":40,"x2":46,"y2":58,"dashed":true,"tone":"muted"},{"t":"dot","x":40,"y":40,"label":"A","labelDx":-4,"labelDy":-2},{"t":"dot","x":64,"y":40,"label":"B","labelDx":4,"labelDy":-2},{"t":"dot","x":46,"y":58,"label":"C","labelDx":-5,"labelDy":4},{"t":"text","x":52,"y":37,"text":"AB = 4","size":3.2,"anchor":"middle"},{"t":"text","x":48.5,"y":49,"text":"S = 6","size":3.4,"anchor":"middle"},{"t":"text","x":12,"y":22,"text":"y = x²−2x−3","size":3.2,"tone":"accent"},{"t":"text","x":43,"y":43.6,"text":"O","size":3.2,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["求与 x 轴的交点：令 y=0，得 x²-2x-3=0，分解因式得 (x-3)(x+1)=0，解得 x₁=-1，x₂=3。","故 A(-1,0)，B(3,0)，底边 AB=3-(-1)=4。","求与 y 轴的交点：令 x=0，得 y=-3，故 C(0,-3)。","底边 AB 在 x 轴上，因此 △ ABC 以 AB 为底时的高就是点 C 纵坐标的绝对值，即 |-3|=3。","求面积：S=12× AB× h=12×4×3=6。"]},{"type":"p","text":"答案：△ ABC 的面积为6。"},{"type":"note","title":"方法小结","text":"与坐标轴的交点坐标要写成有序数对，但底边的长是坐标之差的绝对值，不要直接把横坐标当作长度（如把 B 的横坐标3当成 OB 用错在别处）。"},{"type":"note","title":"例题","text":"已知抛物线 y=-x²+2x+3 与 x 轴交于 A(-1,0)、B(3,0)，与 y 轴交于 C。点 P 是抛物线在直线 BC 上方部分的一个动点，求 △ PBC 面积的最大值及此时点 P 的坐标。"},{"type":"figure","figure":{"id":"fig-m-exa-hanshu-pbc","title":"铅垂法求三角形 PBC 面积的最大值","caption":"P 在抛物线上、直线 BC 上方：过 P 作竖直线交 BC 于 Q，铅垂高 PQ 最大时面积最大，此时 P 的横坐标为 3/2","view":"wide","alt":"平面直角坐标系中开口向下的抛物线 y = -x²+2x+3，与 x 轴交于 A 与 B、与 y 轴交于 C；直线 BC 画出来，点 P 在抛物线上方，从 P 向下的竖直线与 BC 交于点 Q，三角形 PBC 被涂色。","prims":[{"t":"arrow","x1":14,"y1":45.2,"x2":92,"y2":45.2,"tone":"muted"},{"t":"arrow","x1":40.8,"y1":84,"x2":40.8,"y2":10,"tone":"muted"},{"t":"text","x":93,"y":47.2,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":43.2,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":36.8,"y":48.2,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[21.3,64.7],[23.8,57.6],[26.2,51.2],[28.6,45.2],[31.1,39.9],[33.5,35.1],[35.9,30.9],[38.4,27.2],[40.8,24.1],[43.3,21.6],[45.7,19.6],[48.1,18.2],[50.6,17.3],[53,17],[55.4,17.3],[57.9,18.2],[60.3,19.6],[62.8,21.6],[65.2,24.1],[67.6,27.2],[70.1,30.9],[72.5,35.1],[74.9,39.9],[77.4,45.2],[79.8,51.2],[82.3,57.6],[84.7,64.7],[87.1,72.3],[89.6,80.5]],"tone":"accent"},{"t":"line","x1":77.4,"y1":45.2,"x2":40.8,"y2":24.1,"tone":"muted"},{"t":"poly","points":[[59.1,18.8],[77.4,45.2],[40.8,24.1]],"closed":true,"tone":"accent","fill":true},{"t":"line","x1":59.1,"y1":18.8,"x2":59.1,"y2":34.7,"tone":"danger","dashed":true},{"t":"dot","x":28.6,"y":45.2,"label":"A","labelDx":-5.4,"labelDy":-1},{"t":"dot","x":77.4,"y":45.2,"label":"B","labelDx":2.6,"labelDy":-1},{"t":"dot","x":40.8,"y":24.1,"label":"C","labelDx":-5.4,"labelDy":-2.4},{"t":"dot","x":59.1,"y":18.8,"label":"P","labelDx":2.6,"labelDy":-1.4},{"t":"dot","x":59.1,"y":34.7,"label":"Q","labelDx":-5.2,"labelDy":2.4},{"t":"text","x":14,"y":8,"text":"y = -x² + 2x + 3","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":70,"y":30,"text":"PQ 是铅垂高","anchor":"start","size":3.6,"tone":"danger"}]}},{"type":"list","title":"解题步骤","items":["求 C 的坐标：令 x=0，得 y=3，故 C(0,3)。","求直线 BC 的解析式：设 y=kx+b，代入 B(3,0)、C(0,3) 得 k=-1，b=3，故 BC:y=-x+3。","设动点 P 的横坐标为 t（0<t<3），则 P(t,\\ -t²+2t+3)。","用铅垂法：过 P 作竖直线交直线 BC 于 Q(t,\\ -t+3)，铅垂高 PQ=(-t²+2t+3)-(-t+3)=-t²+3t。","水平宽为 B、C 两点横坐标之差的绝对值，即 |3-0|=3。","面积 S=12×3×(-t²+3t)=-32t²+92t，配方得 S=-32(t-32)²+(27)/(8)。","当 t=32 时 S 取得最大值 (27)/(8)，此时 P 的纵坐标为 -94+3+3=(15)/(4)，即 P(32,\\ (15)/(4))。"]},{"type":"p","text":"答案：△ PBC 面积的最大值为 (27)/(8)，此时 P(32,\\ (15)/(4))。"},{"type":"note","title":"方法小结","text":"铅垂高的表达式一定是「抛物线的 y 减直线的 y」，顺序颠倒会得到相反数；另外注意 t 的取值范围必须在两交点之间，最值点若不在范围内就要在端点取到。"},{"type":"note","title":"例题","text":"已知抛物线 y=x²-2mx+2m-1（m 为常数）。求证：无论 m 取何值，该抛物线都经过一个定点，并求出这个定点。"},{"type":"list","title":"解题步骤","items":["把解析式按参数 m 重新分组：y=x²-1+2m(1-x)。","要让 y 的值与 m 无关，只需让含 m 的项的系数为零，即令 1-x=0。","解得 x=1。","把 x=1 代入原式求 y：y=1-2m+2m-1=0，可见 y 确实不含 m。","结论：无论 m 取何值，抛物线恒过定点 (1,0)。"]},{"type":"p","text":"答案：定点为 (1,0)。"},{"type":"note","title":"方法小结","text":"这是「按参数分组、令系数为零」的标准套路。若解析式中含两个参数，则需令两个系数同时为零并联立求解。"},{"type":"note","title":"例题","text":"已知抛物线 y=x²-2x-3 与 x 轴交于 A(-1,0)、B(3,0)，与 y 轴交于点 C(0,-3)。在抛物线上是否存在点 P（不与点 B 重合），使得以 B、C、P 为顶点的三角形是以 B 为直角顶点的直角三角形？若存在，求出点 P 的坐标；若不存在，请说明理由。"},{"type":"figure","figure":{"id":"fig-m-exa-hanshu-zhijiao","title":"以 B 为直角顶点的直角三角形","caption":"抛物线 y = x²-2x-3 上取 P(-2,5)：PB 与 BC 在 B 处画有直角方框，即 ∠PBC = 90°","view":"wide","alt":"平面直角坐标系中开口向上的抛物线 y = x²-2x-3，与 x 轴交于 A、B，与 y 轴交于 C；抛物线上另有一点 P，线段 PB 与 BC 在点 B 处互相垂直，B 处画有直角方框。","prims":[{"t":"arrow","x1":14,"y1":51.9,"x2":92,"y2":51.9,"tone":"muted"},{"t":"arrow","x1":43.8,"y1":84,"x2":43.8,"y2":10,"tone":"muted"},{"t":"text","x":93,"y":53.9,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":46.2,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":39.8,"y":54.9,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[14,10],[16.3,10],[18.6,10],[20.9,17],[23.2,25.1],[25.5,32.6],[27.8,39.6],[30.1,46],[32.4,51.9],[34.6,57.2],[36.9,61.9],[39.2,66.1],[41.5,69.8],[43.8,72.8],[46.1,75.3],[48.4,77.3],[50.7,78.7],[53,79.5],[55.3,79.8],[57.6,79.5],[59.9,78.7],[62.2,77.3],[64.5,75.3],[66.8,72.8],[69.1,69.8],[71.4,66.1],[73.6,61.9],[75.9,57.2],[78.2,51.9],[80.5,46],[82.8,39.6],[85.1,32.6],[87.4,25.1],[89.7,17],[92,10]],"tone":"accent"},{"t":"line","x1":20.9,"y1":17,"x2":78.2,"y2":51.9,"tone":"accent"},{"t":"line","x1":78.2,"y1":51.9,"x2":43.8,"y2":72.8,"tone":"ok"},{"t":"line","x1":74.78,"y1":49.82,"x2":71.37,"y2":51.9,"tone":"muted"},{"t":"line","x1":71.37,"y1":51.9,"x2":74.78,"y2":53.98,"tone":"muted"},{"t":"dot","x":32.4,"y":51.9,"label":"A","labelDx":-4.6,"labelDy":-1.2},{"t":"dot","x":78.2,"y":51.9,"label":"B","labelDx":2.6,"labelDy":-1.2},{"t":"dot","x":43.8,"y":72.8,"label":"C","labelDx":-5.4,"labelDy":-2.4},{"t":"dot","x":20.9,"y":17,"label":"P","labelDx":-5.4,"labelDy":-1.6},{"t":"text","x":20,"y":8,"text":"y = x² - 2x - 3","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":56,"y":40,"text":"PB 垂直于 BC","anchor":"start","size":3.6,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["怎么想到：直角三角形存在性要按直角顶点分类，本题已指定 B 为直角顶点，故只需 PB⊥ BC，于是设出点 P 后用勾股定理的逆定理列方程即可。","设 P(t,\\ t²-2t-3)。用两点间距离公式写出三边的平方：BC²=(3-0)²+(0+3)²=18；PB²=(t-3)²+(t²-2t-3)²；PC²=t²+(t²-2t)²。","以 B 为直角顶点，由勾股定理的逆定理得 PB²+BC²=PC²，即 (t-3)²+(t²-2t-3)²+18=t²+(t²-2t)²。","用平方差化简：(t²-2t-3)²-(t²-2t)²=-3(2t²-4t-3)，代入整理得 -6t²+6t+36=0，即 t²-t-6=0，解得 t=3 或 t=-2；t=3 时 P 与 B 重合，舍去。","当 t=-2 时，y=(-2)²-2×(-2)-3=5，故 P(-2,\\ 5)。回代检验：PB²=25+25=50，PC²=4+64=68，PB²+BC²=50+18=68=PC²，直角关系成立。"]},{"type":"p","text":"答案：存在，点 P 的坐标为 (-2,\\ 5)。"},{"type":"note","title":"方法小结","text":"若题目不指定直角顶点，必须按三个顶点分别作直角顶点讨论；无论哪一类，解出的根都要排除与已知点重合的情形，并回代验证勾股关系。"},{"type":"note","title":"例题","text":"已知抛物线 y=x²-(2m+1)x+m²+m（m 为常数）。（1）求证：无论 m 取何值，该抛物线与 x 轴总有两个不同的交点；（2）设抛物线与 x 轴两交点的横坐标为 x₁、x₂，若 x₁²+x₂²=5，求 m 的值。"},{"type":"list","title":"解题步骤","items":["第（1）问从判别式入手：Δ=(2m+1)²-4(m²+m)=4m²+4m+1-4m²-4m=1。","因为 Δ=1>0 恒成立、与 m 无关，所以无论 m 取何值，抛物线与 x 轴总有两个不同的交点。","第（2）问怎么想到：x₁²+x₂² 不是根与系数的关系直接给出的形式，先配方转化为和与积，即 x₁²+x₂²=(x₁+x₂)²-2x₁x₂。","由根与系数的关系得 x₁+x₂=2m+1，x₁x₂=m²+m，代入得 (2m+1)²-2(m²+m)=5，整理为 2m²+2m+1=5，即 m²+m-2=0。","分解因式得 (m-1)(m+2)=0，解得 m=1 或 m=-2。检验：m=1 时 y=(x-1)(x-2)，两根为1、2，平方和为5；m=-2 时 y=(x+1)(x+2)，两根为 -1、-2，平方和为5，均符合题意。"]},{"type":"p","text":"答案：（1）判别式恒等于1、大于0，故抛物线与 x 轴总有两个不同的交点；（2）m=1 或 m=-2。"},{"type":"note","title":"方法小结","text":"见到 x₁²+x₂²、|x₁-x₂| 这类对称式，先统一转化为 x₁+x₂ 与 x₁x₂ 再用根与系数的关系；使用之前必须先验证判别式非负，否则两根可能不存在。"},{"type":"list","title":"易错点","items":["忽略 $x$ 的取值范围：抛物线上的动点只能在题目限定的区间（如两交点之间）内运动，配方求得的最值点若越界，最值实际在端点取到。","铅垂高顺序写反：必须用「抛物线的函数值减直线的函数值」，写成相反数会导致面积恒为负或最值判断错误。","联立后忘记检验判别式：用韦达定理处理含参交点问题时，若不先确认 $\\Delta\\geq0$，可能得到实际上不存在的交点。","存在性问题分类不全：等腰三角形要按三条边分别作腰讨论，直角三角形要按三个顶点分别作直角顶点讨论，漏一类即扣分。","求出坐标后不回代检验：动点是否在抛物线上、是否与已知点重合、是否满足题设不等式条件，都必须验证。","计算粗心链式失分：函数压轴题步骤长，一步符号错误会导致后续全错，因此每一步都要写清楚，便于检查时快速定位。"]},{"type":"list","title":"解题方法","items":["求解析式先挑形式：给三点用一般式，给顶点或最值用顶点式，给两根用交点式，选定形式再列方程，能显著减少计算量。","交点问题联立消元：把直线与抛物线联立得到一元二次方程，交点横坐标即方程的根；含参时借助韦达定理整体处理，不急于求根。","面积问题用铅垂法：过动点作竖直线，把面积写成水平宽与铅垂高乘积的一半，面积最值随即转化为二次函数最值。","定点问题按参数分组：含参数的项集中后令参数系数为零，解出定点坐标，这是恒过定点类问题的固定解法。","存在性问题设点列方程：设动点坐标为 (t,\\ at²+bt+c)，用距离平方、相似比或面积关系列方程，按分类标准逐一讨论，最后统一检验范围。","数形结合定范围：动手前先画草图，标出交点、顶点与对称轴，很多分类讨论的边界与取值范围的限制在图上就能看清。"]}],"questions":[{"id":"m-exa-hanshu-yazhou-q1","type":"fill","stem":"抛物线 y=x²-2x-3 与 x 轴交于 A、B 两点，则线段 AB 的长为____。","answer":"4","explain":"令 y=0 得 x²-2x-3=0，分解因式得 (x-3)(x+1)=0，故两根为 x₁=-1，x₂=3，即 A(-1,0)、B(3,0)。所以 AB=|3-(-1)|=4。也可用根与系数的关系验算：AB=|x₁-x₂|=√((x₁+x₂)²-4x₁x₂)=√(4+12)=4。","difficulty":1,"tags":["二次函数","与坐标轴交点"],"figure":{"id":"fig-m-exa-hanshu-ab","title":"抛物线与 x 轴的两个交点","caption":"y = x²-2x-3 与 x 轴交于 A(-1,0)、B(3,0)，线段 AB 的长就是两交点横坐标之差的绝对值 4","view":"wide","alt":"平面直角坐标系中开口向上的抛物线 y = x²-2x-3 与 x 轴交于两点 A 与 B，两点之间的线段被加粗标出。","prims":[{"t":"arrow","x1":14,"y1":51.9,"x2":92,"y2":51.9,"tone":"muted"},{"t":"arrow","x1":43.8,"y1":84,"x2":43.8,"y2":10,"tone":"muted"},{"t":"text","x":93,"y":53.9,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":46.2,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":39.8,"y":54.9,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[14,10],[16.3,10],[18.6,10],[20.9,17],[23.2,25.1],[25.5,32.6],[27.8,39.6],[30.1,46],[32.4,51.9],[34.6,57.2],[36.9,61.9],[39.2,66.1],[41.5,69.8],[43.8,72.8],[46.1,75.3],[48.4,77.3],[50.7,78.7],[53,79.5],[55.3,79.8],[57.6,79.5],[59.9,78.7],[62.2,77.3],[64.5,75.3],[66.8,72.8],[69.1,69.8],[71.4,66.1],[73.6,61.9],[75.9,57.2],[78.2,51.9],[80.5,46],[82.8,39.6],[85.1,32.6],[87.4,25.1],[89.7,17],[92,10]],"tone":"accent"},{"t":"line","x1":32.4,"y1":51.9,"x2":78.2,"y2":51.9,"tone":"danger","width":1.4},{"t":"dot","x":32.4,"y":51.9,"label":"A","labelDx":-4.6,"labelDy":-1.2},{"t":"dot","x":78.2,"y":51.9,"label":"B","labelDx":2.6,"labelDy":-1.2},{"t":"text","x":50,"y":74,"text":"AB = ?","anchor":"middle","size":3.6,"tone":"danger"}]}},{"id":"m-exa-hanshu-yazhou-q2","type":"fill","stem":"将直线 y=2x-1 向上平移3个单位长度，所得直线与 y 轴交点的纵坐标为____。","answer":"2","explain":"直线向上平移 m 个单位长度只改变截距：y=2x-1 向上平移3个单位得 y=2x-1+3=2x+2。令 x=0 得 y=2，故与 y 轴交点为 (0,2)，纵坐标为2。注意平移不改变斜率。","difficulty":1,"tags":["一次函数","图象平移"]},{"id":"m-exa-hanshu-yazhou-q3","type":"choice","stem":"无论 m 取何实数，抛物线 y=x²-2mx+2m-1 都一定经过的定点是（　）","answer":"A","explain":"按参数 m 分组：y=x²-1+2m(1-x)。要使 y 与 m 无关，需令 1-x=0，得 x=1；此时 y=1-1+0=0。故抛物线恒过定点 (1,0)。验证其他选项：把 x=0 代入得 y=2m-1，随 m 变化，不是定点。","options":["(1,0)","(0,-1)","(2,3)","(-1,0)"],"difficulty":2,"tags":["恒过定点","二次函数"]},{"id":"m-exa-hanshu-yazhou-q4","type":"choice","stem":"抛物线 y=-x²+2x+3 与 x 轴交于 A(-1,0)、B(3,0)，与 y 轴交于 C(0,3)。点 P 是抛物线在直线 BC 上方部分的动点，当 △ PBC 面积最大时，点 P 的横坐标为（　）","answer":"B","explain":"直线 BC 过 B(3,0)、C(0,3)，解析式为 y=-x+3。设 P(t,\\ -t²+2t+3)，则铅垂高 PQ=(-t²+2t+3)-(-t+3)=-t²+3t，水平宽为3，故 S=12×3×(-t²+3t)=-32(t-32)²+(27)/(8)。当 t=32 时面积最大，且 0<32<3 在允许范围内。故选B。","options":["1","32","2","52"],"difficulty":3,"tags":["面积最值","铅垂法"],"figure":{"id":"fig-m-exa-hanshu-pbc2","title":"面积最大时动点 P 的位置","caption":"P 在抛物线上、直线 BC 上方，铅垂高 PQ 越大三角形 PBC 的面积越大；PQ 最大时 P 的横坐标为 3/2","view":"wide","alt":"平面直角坐标系中开口向下的抛物线 y = -x²+2x+3，A 与 B 是与 x 轴的交点、C 是与 y 轴的交点；直线 BC 与抛物线上一点 P 连成三角形 PBC，从 P 向下的竖直线与 BC 交于 Q。","prims":[{"t":"arrow","x1":14,"y1":45.2,"x2":92,"y2":45.2,"tone":"muted"},{"t":"arrow","x1":40.8,"y1":84,"x2":40.8,"y2":10,"tone":"muted"},{"t":"text","x":93,"y":47.2,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":43.2,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":36.8,"y":48.2,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[21.3,64.7],[23.8,57.6],[26.2,51.2],[28.6,45.2],[31.1,39.9],[33.5,35.1],[35.9,30.9],[38.4,27.2],[40.8,24.1],[43.3,21.6],[45.7,19.6],[48.1,18.2],[50.6,17.3],[53,17],[55.4,17.3],[57.9,18.2],[60.3,19.6],[62.8,21.6],[65.2,24.1],[67.6,27.2],[70.1,30.9],[72.5,35.1],[74.9,39.9],[77.4,45.2],[79.8,51.2],[82.3,57.6],[84.7,64.7],[87.1,72.3],[89.6,80.5]],"tone":"accent"},{"t":"line","x1":77.4,"y1":45.2,"x2":40.8,"y2":24.1,"tone":"muted"},{"t":"poly","points":[[59.1,18.8],[77.4,45.2],[40.8,24.1]],"closed":true,"tone":"accent","fill":true},{"t":"line","x1":59.1,"y1":18.8,"x2":59.1,"y2":34.7,"tone":"danger","dashed":true},{"t":"dot","x":28.6,"y":45.2,"label":"A","labelDx":-5.4,"labelDy":-1},{"t":"dot","x":77.4,"y":45.2,"label":"B","labelDx":2.6,"labelDy":-1},{"t":"dot","x":40.8,"y":24.1,"label":"C","labelDx":-5.4,"labelDy":-2.4},{"t":"dot","x":59.1,"y":18.8,"label":"P","labelDx":2.6,"labelDy":-1.4},{"t":"dot","x":59.1,"y":34.7,"label":"Q","labelDx":-5.2,"labelDy":2.4},{"t":"text","x":14,"y":8,"text":"y = -x² + 2x + 3","anchor":"start","size":3.6,"tone":"accent"}]}},{"id":"m-exa-hanshu-yazhou-q5","type":"short","stem":"已知抛物线 y=x²-2x-3 与 x 轴交于点 A、B（A 在 B 左侧），与 y 轴交于点 C。在抛物线上是否存在点 P，使 △ ABP 的面积等于 △ ABC 面积的2倍？若存在，求出点 P 的坐标；若不存在，请说明理由。","answer":"由 $y=0$ 得 $x^2-2x-3=0$，解得 $x=-1$ 或 $x=3$，故 $A(-1,0)$，$B(3,0)$，$AB=4$。由 $x=0$ 得 $y=-3$，故 $C(0,-3)$，$\\triangle ABC$ 以 $AB$ 为底时高为3，面积 $S_{\\triangle ABC}=\\frac12\\times4\\times3=6$。设 $P(t,\\ t^2-2t-3)$，则 $\\triangle ABP$ 以 $AB=4$ 为底，高为 $|t^2-2t-3|$，故 $S_{\\triangle ABP}=\\frac12\\times4\\times|t^2-2t-3|=2|t^2-2t-3|$。由题意 $2|t^2-2t-3|=12$，即 $|t^2-2t-3|=6$，分两种情况讨论：① $t^2-2t-3=6$，即 $t^2-2t-9=0$，解得 $t=1\\pm\\sqrt{10}$；② $t^2-2t-3=-6$，即 $t^2-2t+3=0$，判别式 $\\Delta=4-12=-8<0$，无实数解。当 $t=1+\\sqrt{10}$ 时 $y=6$；当 $t=1-\\sqrt{10}$ 时 $y=6$。两部分点均在抛物线上且不与 $A$、$B$ 重合，故存在满足条件的点 $P$，坐标为 $(1+\\sqrt{10},\\ 6)$ 与 $(1-\\sqrt{10},\\ 6)$。","explain":"本题考查抛物线中的存在性问题，标准解法是「设点——表示面积——列方程——分类讨论——检验」。设 P 的坐标为 (t,\\ t²-2t-3) 后，由于 AB 在 x 轴上，△ ABP 的高就是 P 纵坐标的绝对值 |t²-2t-3|。这里必须加绝对值，否则会漏掉 P 在 x 轴下方的情形，而本题恰好正解全部落在 x 轴下方（y=6 对应的是 P 在 x 轴上方的另一种可能，需通过方程判断）。列方程得 |t²-2t-3|=6 后，必须化为两个一元二次方程分别求解：t²-2t-9=0 有解 t=1±√(10)，而 t²-2t+3=0 因判别式为负而无实数解。最后还要验证所得点在抛物线上、且不与 A、B 重合，保证答案完备。","difficulty":3,"tags":["存在性问题","面积","分类讨论"],"rubric":["正确求出 A、B、C 的坐标并算出 S_(△ ABC)=6","设出动点 P 的坐标并正确写出 △ ABP 面积的表达式（含绝对值）","利用面积关系列出方程 |t²-2t-3|=6","对绝对值方程分类讨论，得到两个方程","正确解出 t=1±√(10)，并说明另一个方程因判别式小于零而无解","写出完整的点 P 坐标并检验其在抛物线上且不与 A、B 重合"],"figure":{"id":"fig-m-exa-hanshu-mianji2","title":"高加倍：面积翻倍的两个点 P","caption":"三角形 ABC 以 AB 为底、高为 3；要使三角形 ABP 的面积是它的 2 倍，P 到 x 轴的距离必须为 6，即 P 落在直线 y = 6 与抛物线的交点上","view":"wide","alt":"平面直角坐标系中开口向上的抛物线 y = x²-2x-3，与 x 轴交于 A、B，与 y 轴交于 C，三角形 ABC 被涂色；一条水平的虚线 y = 6 与抛物线交于两点 P，标出这两个点。","prims":[{"t":"arrow","x1":14,"y1":53.2,"x2":92,"y2":53.2,"tone":"muted"},{"t":"arrow","x1":43.7,"y1":84,"x2":43.7,"y2":10,"tone":"muted"},{"t":"text","x":93,"y":55.2,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":46.1,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":39.7,"y":56.2,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[14,10],[15.9,10],[17.7,10],[19.6,10],[21.4,10],[23.3,14.7],[25.1,22.3],[27,29.5],[28.9,36.1],[30.7,42.3],[32.6,48],[34.4,53.2],[36.3,57.9],[38.1,62],[40,65.7],[41.9,69],[43.7,71.7],[45.6,73.9],[47.4,75.6],[49.3,76.8],[51.1,77.6],[53,77.8],[54.9,77.6],[56.7,76.8],[58.6,75.6],[60.4,73.9],[62.3,71.7],[64.1,69],[66,65.7],[67.9,62],[69.7,57.9],[71.6,53.2],[73.4,48],[75.3,42.3],[77.1,36.1],[79,29.5],[80.9,22.3],[82.7,14.7],[84.6,10],[86.4,10],[88.3,10],[90.1,10],[92,10]],"tone":"accent"},{"t":"poly","points":[[34.4,53.2],[71.6,53.2],[43.7,71.7]],"closed":true,"tone":"accent","fill":true},{"t":"line","x1":82.4,"y1":16.2,"x2":23.6,"y2":16.2,"tone":"danger","dashed":true},{"t":"dot","x":34.4,"y":53.2,"label":"A","labelDx":-4.6,"labelDy":-1.2},{"t":"dot","x":71.6,"y":53.2,"label":"B","labelDx":2.6,"labelDy":-1.2},{"t":"dot","x":43.7,"y":71.7,"label":"C","labelDx":-5.4,"labelDy":-2.4},{"t":"dot","x":82.4,"y":16.2,"label":"P","labelDx":2.6,"labelDy":-1.4},{"t":"dot","x":23.6,"y":16.2,"label":"P′","labelDx":-6,"labelDy":-1.4},{"t":"text","x":60,"y":12,"text":"y = 6","anchor":"start","size":3.6,"tone":"danger"},{"t":"text","x":50,"y":78,"text":"S(ABP) = 2 × S(ABC)","anchor":"middle","size":3.6,"tone":"accent"}]}},{"id":"m-exa-hanshu-yazhou-z1","type":"choice","stem":"二次函数 y=x²-2mx+3（m 为常数），若当 x≥1 时，y 随 x 的增大而增大，则 m 的取值范围是（　）","answer":"D","explain":"抛物线开口向上，对称轴为直线 x=m，且开口向上的抛物线在对称轴右侧 y 随 x 的增大而增大。要使当 x≥1 时 y 随 x 的增大而增大，区间 x≥1 必须整体落在对称轴的右侧（含恰从对称轴开始），故 m≤1，故选D。易错点：把条件误解为对称轴恰是 x=1，或漏掉端点可以重合的情形而误选 m<1。","options":["m≥1","m≤-1","m≥-1","m≤1"],"difficulty":2,"tags":["二次函数","增减性"]},{"id":"m-exa-hanshu-yazhou-z2","type":"short","stem":"已知一次函数 y=kx+b 的图象与反比例函数 y=(m)/(x) 的图象交于点 A(1,\\ 4) 和点 B(4,\\ n)。（1）求反比例函数与一次函数的解析式；（2）求 △ AOB 的面积（O 为坐标原点）；（3）结合图象，直接写出不等式 kx+b>(m)/(x) 的解集。","answer":"（1）把 $A(1,4)$ 代入 $y=\\dfrac{m}{x}$ 得 $m=4$，故反比例函数为 $y=\\dfrac{4}{x}$；把 $B(4,n)$ 代入得 $n=1$，故 $B(4,1)$。把 $A(1,4)$、$B(4,1)$ 代入 $y=kx+b$，由 $k+b=4$ 与 $4k+b=1$ 联立解得 $k=-1$，$b=5$，故一次函数为 $y=-x+5$。（2）直线与 $y$ 轴交于 $D(0,5)$，点 $A$ 在 $D$、$B$ 之间，故 $S_{\\triangle AOB}=S_{\\triangle BOD}-S_{\\triangle AOD}=\\dfrac12\\times5\\times4-\\dfrac12\\times5\\times1=10-2.5=7.5$。（3）解集为 $x<0$ 或 $1<x<4$。","explain":"本题考查反比例函数与一次函数的综合。第（1）问的关键顺序是先用点 A 定双曲线，再用双曲线定 B 的纵坐标，最后用待定系数法定直线，环环相扣不能跳步。第（2）问两个交点都不在坐标轴上，标准动作是借直线与 y 轴的交点作割补：D、A、B 三点共线且 A 居中，故用大三角形 BOD 减去小三角形 AOD，底 OD=5，高分别取 B、A 的横坐标。第（3）问必须数形结合：不等式成立即一次函数图象位于双曲线上方，按交点横坐标分段观察；注意双曲线在第三象限也有图象，当 x<0 时直线恒在双曲线上方，只答 1<x<4 会漏掉一整段。","difficulty":3,"tags":["反比例函数","一次函数","数形结合"],"rubric":["由点 A(1,4) 求出 m=4，进而求得 B(4,1)，并用待定系数法求出一次函数 y=-x+5","正确作割补并表示出 △ AOB 的面积，算得 7.5","数形结合写出完整解集 x<0 或 1<x<4，不漏 x<0 的部分"],"figure":{"id":"fig-m-exa-hanshu-fanbili","title":"一次函数与反比例函数的图象与三角形 AOB","caption":"点 A(1,4)、B(4,1) 是 y = 4/x 与 y = -x+5 的交点；直线交 y 轴于 D(0,5)，三角形 AOB 的面积用大三角形 BOD 减小三角形 AOD 得到","view":"wide","alt":"平面直角坐标系中第一象限与第三象限各有一段反比例函数 y = 4/x 的图象，一条直线 y = -x+5 与第一象限的曲线交于 A、B 两点并与 y 轴交于 D；原点 O 与 A、B 连成三角形并涂色。","prims":[{"t":"arrow","x1":14,"y1":53.2,"x2":92,"y2":53.2,"tone":"muted"},{"t":"arrow","x1":45.2,"y1":84,"x2":45.2,"y2":10,"tone":"muted"},{"t":"text","x":93,"y":55.2,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":47.6,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":41.2,"y":56.2,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[50,13.4],[50.8,18.9],[51.6,23.1],[52.4,26.4],[53.2,29],[53.9,31.1],[54.7,32.9],[55.5,34.5],[56.3,35.8],[57.1,36.9],[57.8,37.9],[58.6,38.8],[59.4,39.6],[60.2,40.3],[61,41],[61.7,41.5],[62.5,42.1],[63.3,42.5],[64.1,43],[64.9,43.4],[65.6,43.8],[66.4,44.1],[67.2,44.4],[68,44.7],[68.8,45],[69.5,45.3],[70.3,45.5],[71.1,45.7],[71.9,46],[72.7,46.2],[73.4,46.4],[74.2,46.5],[75,46.7],[75.8,46.9],[76.6,47],[77.3,47.2],[78.1,47.3],[78.9,47.5],[79.7,47.6],[80.5,47.7],[81.2,47.8],[82,47.9],[82.8,48],[83.6,48.2],[84.4,48.3],[85.1,48.3],[85.9,48.4],[86.7,48.5],[87.5,48.6],[88.3,48.7],[89,48.8],[89.8,48.9],[90.6,48.9],[91.4,49]],"tone":"accent"},{"t":"curve","points":[[14,59.3],[14.8,59.5],[15.6,59.7],[16.3,59.8],[17.1,60],[17.9,60.2],[18.7,60.4],[19.5,60.6],[20.2,60.9],[21,61.1],[21.8,61.4],[22.6,61.7],[23.4,62],[24.1,62.3],[24.9,62.7],[25.7,63],[26.5,63.4],[27.3,63.9],[28,64.4],[28.8,64.9],[29.6,65.5],[30.4,66.1],[31.2,66.9],[31.9,67.7],[32.7,68.6],[33.5,69.6],[34.3,70.8],[35.1,72.1],[35.8,73.7],[36.6,75.6],[37.4,77.8]],"tone":"accent"},{"t":"curve","points":[[33.5,13.1],[37.4,16.2],[41.3,19.3],[45.2,22.3],[49.1,25.4],[53,28.5],[56.9,31.6],[60.8,34.7],[64.7,37.8],[68.6,40.8],[72.5,43.9],[76.4,47],[80.3,50.1],[84.2,53.2],[88.1,56.3],[92,59.3]],"tone":"ok"},{"t":"poly","points":[[45.2,53.2],[53,28.5],[76.4,47]],"closed":true,"tone":"danger","fill":true},{"t":"line","x1":45.2,"y1":22.3,"x2":53,"y2":28.5,"tone":"muted","dashed":true},{"t":"dot","x":45.2,"y":53.2,"label":"O","labelDx":-4.6,"labelDy":3.2},{"t":"dot","x":53,"y":28.5,"label":"A","labelDx":3,"labelDy":-1.4},{"t":"dot","x":76.4,"y":47,"label":"B","labelDx":2.8,"labelDy":2.8},{"t":"dot","x":45.2,"y":22.3,"label":"D","labelDx":-5.4,"labelDy":-1.6},{"t":"text","x":78,"y":20,"text":"y = 4/x","anchor":"end","size":3.6,"tone":"accent"},{"t":"text","x":18,"y":60,"text":"y = -x + 5","anchor":"start","size":3.6,"tone":"ok"},{"t":"text","x":50,"y":90,"text":"1 < x < 4 时直线在双曲线上方；x < 0 时也成立","anchor":"middle","size":3.6,"tone":"muted"}]}}]},{"id":"m-exa-yingyong-tuili","title":"应用题与规律探究题","subtitle":"中考 · 题型突破","grade":"all","tags":["中考应试","题型突破"],"blocks":[{"type":"note","title":"教材章节","text":"中考 · 题型突破"},{"type":"note","title":"一句话概述","text":"掌握增长率、利润、测量建模与规律探究的套路，把文字题翻译成方程与函数。"},{"type":"h","text":"核心概念"},{"type":"p","text":"应用与建模题的分值位置（官方口径）：据广州市教育局2025年12月5日印发的《2027—2029年广州市初中学业水平考试录取计分科目考试实施方案》，数学满分150分、时长120分钟，客观题合计64分、占全卷42.7%；方案强调「强化命题核心素养导向，优化试题情境创设」，并要求减少单纯记忆与机械训练类试题、增加综合性应用性探究性题目。这直接指向应用题与阅读探究题的分量会继续加大。来源：广州市教育局官网政策解读（2025年12月）。"},{"type":"p","text":"现行卷中的应用题位置：现行（2024—2026年）卷为选择10题共30分、填空6题共18分、解答9题共72分。实际应用与建模通常占据解答题中段的两到三道，且常以长文字材料呈现，如以果园采摘、隧道限高、演讲比赛评分等真实情境为背景。"},{"type":"p","text":"增长率（降低率）问题：识别特征：连续两次（或多次）以相同的百分率增长或降低。基本关系是「原量乘以 (1± x) 的 n 次方等于变化后的量」。关键是先判断是增长还是降低，从而确定取加号还是减号；两次降低时若设降率为 x，则方程为 a(1-x)²=b，注意结果要舍去不符合实际意义的根。"},{"type":"p","text":"销售利润问题：识别特征：给出每件进价、售价与销售量，并说明「每降价（涨价）1元，销量增加（减少）若干件」。基本模型是「总利润 = 每件利润 × 销售量」，其中每件利润与销售量都随调价量 x 变化，整理后得到一个关于 x 的二次函数，配方即可求最大利润。要注意 x 的取值范围由实际意义限定。"},{"type":"p","text":"工程、行程与配比问题：识别特征：出现工作效率、工作时间、工作总量，或速度、时间、路程，且常以「比另一组多用或少用若干天（小时）」的形式给出条件。设未知数后列分式方程，解出后必须检验两件事：一是分母不为零，二是结果是否符合实际意义（如人数为正整数、时间大于零）。"},{"type":"p","text":"测量与三角函数建模：识别特征：出现坡角、坡度、仰角、俯角、限高、跨度等词。核心是构造直角三角形，把已知的角与边对应到正弦、余弦、正切上。坡比定义为竖直高度与水平宽度的比，等于坡角的正切值。若图形中只有一个直角三角形不够用，就作高把它拆成两个，用公共边建立联系。"},{"type":"p","text":"规律探究题：识别特征：给出一串数或一组逐步增加的图形，要求写出第 n 个的一般表达式。通用三步：先写出前几项的具体值，再比较相邻两项的差（一阶差）判断是等差或等比，最后用「首项 + 公差 × (n-1)」或等比公式写出通项。若是图形规律，还要同时观察「每一次增加多少个基本单位」以及「是否有不随 n 变化的固定部分」。"},{"type":"p","text":"新定义与阅读探究题：识别特征：题干先给一段材料定义一个新概念（如黄金矩形）或记录一次研究过程，再据此提问。应对步骤：先把定义中的文字逐句翻译成数学条件并标注在图上，再核对题目所给的操作步骤产生了哪些等量关系（如折叠必产生全等），最后把问题化归为已学的相似、方程或函数。读题时务必把关键数据（角度值、长度、精确度要求）圈出来。"},{"type":"note","title":"中考考法","text":"读题先定模型再动笔\n长文字题先用三行法压缩：已知什么、求什么、用什么关系。连续两次相同百分率用平方模型，每涨降1元销量增减若干件用利润模型，给效率与时间就列分式方程，模型定错后面全错。"},{"type":"note","title":"中考考法","text":"解方程后的双检验动作\n分式方程解出后必须检验两件事：分母不为零、结果符合实际意义（人数为正整数、时间大于零）；二次方程的双根按情境取舍，增长率要满足 0<x<1，不写检验过程会扣过程分。"},{"type":"note","title":"中考考法","text":"函数建模题三件套写全\n利润、面积类应用题答案必须齐三件：函数关系式、自变量取值范围、最值与答句。配方求最值前先确认顶点横坐标在范围内，越界则比较端点函数值取更优者，漏写范围即使算对也算不完整。"},{"type":"note","title":"中考考法","text":"测量与图形规律的分步踩分\n解直角三角形建模先设公共边、再写两个三角形中的三角函数关系，结果带单位并按精确度要求取值；规律探究先列前三到五项再求一阶差，通项必须代回已知项验证后再写结论。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["平均变化率公式","a 为原量，x 为每次增长（降低）的百分率，b 为经过两次变化后的量。","增长用加号，降低用减号；解出的两个根要按实际意义取舍，通常舍去大于1或为负的根。"],["销售利润模型","W 为总利润，p 为售价，c 为每件成本，q 为销售量。","调价后 p 与 q 都随调价量变化，整理成关于调价量的二次函数再配方；注意调价量的取值范围由实际意义限定。"],["速度公式","s 为路程，v 为速度，t 为时间。","工程问题中「工作总量 = 工作效率 × 工作时间」与之同构，可平行记忆。"],["坡度（坡比）与坡角","h 为竖直高度，l 为水平宽度，α 为坡角。","坡度是竖直高度与水平宽度之比，不是与斜面长度之比；沿斜面走了一段距离求上升高度时，用的是斜面长乘以 sinα。"],["直角三角形中的边角关系","在 △ ABC 中，∠ C=90^°。","测量题的标准动作是「先作高、再找公共边」；只有一个直角三角形不够用时，用公共边把两个三角形串起来。"],["等差数列通项","a₁ 为首项，d 为公差（即相邻两项的差）。","规律探究题中，若相邻两项的差恒定，即得此模型；图形规律题要先算出每次新增的基本单位数作为 d，再求首项。"]]},{"type":"note","title":"例题","text":"某商品原价100元，因市场原因连续两次降价，每次降价的百分率相同。两次降价后售价为81元。求每次降价的百分率。"},{"type":"list","title":"解题步骤","items":["设每次降价的百分率为 x，由「降价」确定用减号模型 a(1-x)²=b。","代入数据得 100(1-x)²=81。","两边同除以100得 (1-x)²=0.81。","开平方得 1-x=0.9 或 1-x=-0.9，即 x=0.1 或 x=1.9。","检验实际意义：降价的百分率必须满足 0<x<1，故舍去 x=1.9。","结论：每次降价的百分率为 10\\%。"]},{"type":"p","text":"答案：每次降价的百分率为 10\\%。"},{"type":"note","title":"方法小结","text":"开平方后会得到两个根，必须回到题目情境中检验取舍；此外若第二次降价与第一次降率不同，则不能使用平方模型，需分别设未知数。"},{"type":"note","title":"例题","text":"某商品每件进价40元，按每件60元销售时，每天可售出100件。市场调查发现，每件售价每降低1元，每天的销售量就增加10件。设每件降价 x 元，求每天销售利润 W（元）关于 x 的函数关系式，并求每天的最大利润。"},{"type":"list","title":"解题步骤","items":["确定每件利润：原售价60元，降价 x 元后售价为 (60-x) 元，故每件利润为 (60-x)-40=(20-x) 元。","确定销售量：每降价1元多售10件，故降价 x 元后每天销售量为 (100+10x) 件。","由「总利润 = 每件利润 × 销售量」得 W=(20-x)(100+10x)。","展开整理：W=2000+200x-100x-10x²=-10x²+100x+2000。","配方求最值：W=-10(x²-10x)+2000=-10(x-5)²+250+2000=-10(x-5)²+2250。","确定取值范围：售价不能低于进价，故 20-x>0 即 x<20，且 x≥0，x=5 在范围内。","结论：W=-10x²+100x+2000（0≤ x<20），当每件降价5元（即售价55元）时每天利润最大，为2250元。"]},{"type":"p","text":"答案：W=-10x²+100x+2000（0≤ x<20）；当 x=5 时每天利润最大，最大利润为2250元。"},{"type":"note","title":"方法小结","text":"这类题最容易漏写取值范围和「答」这一步；最大利润必须回答「此时售价是多少」，否则算答非所问。"},{"type":"note","title":"例题","text":"用火柴棒按规律搭图形：第1个图形用4根火柴棒，第2个图形用7根，第3个图形用10根，依此类推且每次增加的根数相同。求第 n 个图形所用的火柴棒根数，并求第20个图形所用的根数。"},{"type":"list","title":"解题步骤","items":["列出前几项：a₁=4，a₂=7，a₃=10。","求相邻两项的差：7-4=3，10-7=3，差恒定，故为等差数列。","确定首项与公差：a₁=4，d=3。","写出通项：a_n=a₁+(n-1)d=4+3(n-1)=3n+1。","验证：n=1 得4，n=2 得7，n=3 得10，与已知一致。","求第20项：a₂₀=3×20+1=61。","结论：第 n 个图形用 (3n+1) 根火柴棒，第20个图形用61根。"]},{"type":"p","text":"答案：第 n 个图形用 (3n+1) 根；第20个图形用61根。"},{"type":"note","title":"方法小结","text":"规律探究必须用前几项验证通项，不能只凭观察就下结论；若相邻差在逐渐变化（如差为2、4、6），则需考虑二次型的表达式。"},{"type":"note","title":"例题","text":"某数学兴趣小组要测量学校旗杆 AB 的高度。小组同学在地面上的点 C 处测得旗杆顶端 A 的仰角为 30^(°)，沿 CB 方向朝旗杆前进20米到达点 D 处，测得顶端 A 的仰角为 60^(°)。点 B 为旗杆底部，C、D、B 在同一水平直线上，测角仪器的高度忽略不计。求旗杆 AB 的高度（结果保留根号）。"},{"type":"figure","figure":{"id":"fig-m-exa-tuili-1","title":"双仰角测旗杆","caption":"在 D 处测仰角 60°、C 处测仰角 30°，CB − DB = 20，解得 h = 10√3 米（约 17.3 米）","view":"wide","alt":"地面上的旗杆 AB，从较近的 D 点测杆顶 A 的仰角为 60 度，从较远的 C 点测仰角为 30 度，C 与 D 相距 20 米，图中标注两个仰角与 CD 的距离","prims":[{"t":"line","x1":16,"y1":76,"x2":88,"y2":76,"tone":"muted"},{"t":"hatch","x":16,"y":76,"w":72,"h":3,"tone":"muted"},{"t":"line","x1":30,"y1":76,"x2":30,"y2":48.3,"tone":"main","width":2},{"t":"poly","points":[[30,48.3],[30,52.5],[37,50.4]],"closed":true,"tone":"main","fill":true},{"t":"line","x1":30,"y1":48.3,"x2":46,"y2":76,"tone":"accent"},{"t":"line","x1":30,"y1":48.3,"x2":78,"y2":76,"tone":"accent"},{"t":"angle","x":46,"y":76,"from":180,"to":240,"r":9,"label":"60°","tone":"accent"},{"t":"angle","x":78,"y":76,"from":180,"to":210,"r":9,"label":"30°","tone":"accent"},{"t":"line","x1":46,"y1":76,"x2":46,"y2":84,"dashed":true,"tone":"muted"},{"t":"line","x1":78,"y1":76,"x2":78,"y2":84,"dashed":true,"tone":"muted"},{"t":"arrow","x1":46,"y1":84,"x2":78,"y2":84,"both":true,"label":"20 米","labelDy":4},{"t":"text","x":24.5,"y":62,"text":"h","size":3.4,"anchor":"end"},{"t":"dot","x":30,"y":48.3,"label":"A","labelDx":-4,"labelDy":-2},{"t":"dot","x":30,"y":76,"label":"B","labelDx":-5,"labelDy":4},{"t":"dot","x":46,"y":76,"label":"D","labelDx":-4,"labelDy":4},{"t":"dot","x":78,"y":76,"label":"C","labelDx":5,"labelDy":4}]}},{"type":"list","title":"解题步骤","items":["怎么想到：两个仰角对应两个直角三角形，单独哪一个都解不出，桥是公共边 AB 与水平关系 CB-DB=CD=20 米，故设 AB=h 米后分别表示 CB 与 DB。","在直角三角形 ABD 中，tan60^(°)=(AB)/(DB)，故 DB=htan60^(°)=(3)/(3)h；在直角三角形 ABC 中，tan30^(°)=(AB)/(CB)，故 CB=htan30^(°)=3 h。","由 CB-DB=20 得 3 h-(3)/(3)h=20，即 (23)/(3)h=20，解得 h=103。","用几何法校验：由外角性质，∠ CAD=60^(°)-30^(°)=30^(°)=∠ ACD，故 △ ACD 是等腰三角形，AD=CD=20；在直角三角形 ABD 中，AB=AD·sin60^(°)=20×(3)/(2)=103，两种方法结果一致。","结论：旗杆 AB 的高度为 103 米（约17.3米）。"]},{"type":"p","text":"答案：旗杆 AB 的高度为 103 米。"},{"type":"note","title":"方法小结","text":"测量题的通用动作是「设公共边、找两个三角形之间的长度关系」；若两个仰角中较大角是较小角的2倍，优先用外角构造等腰三角形，可以大幅减少计算量。"},{"type":"note","title":"例题","text":"某隧道入口的横截面以路面所在直线为 x 轴、隧道中线为 y 轴建立平面直角坐标系，顶部轮廓为抛物线的一部分。已知抛物线顶点离路面6米，抛物线与路面两交点之间的距离为12米。（1）求该抛物线的解析式；（2）一辆宽4米、高4.8米的货车沿隧道中线行驶，能否安全通过该隧道？请说明理由。"},{"type":"list","title":"解题步骤","items":["怎么想到：以对称轴为 y 轴、路面为 x 轴，顶点为 (0,6)；由跨度12米且关于中线对称，抛物线与 x 轴的两交点为 (-6,0) 和 (6,0)，已知与 x 轴交点时用交点式设解析式最省力。","设 y=a(x+6)(x-6)，把顶点 (0,6) 代入：6=a×6×(-6)=-36a，解得 a=-16。","故抛物线的解析式为 y=-16(x+6)(x-6)=-16x²+6（-6≤ x≤6）。","货车宽4米且沿中线行驶，车身边缘到中线的水平距离为 4÷2=2 米，即最外沿对应 x=±2。当 x=2 时，y=-16×4+6=-23+6=(16)/(3)≈5.33 米。","因为车身边缘正上方隧道的高度 (16)/(3)≈5.33 米大于车高4.8米，所以货车能安全通过该隧道。"]},{"type":"p","text":"答案：（1）y=-16x²+6（-6≤ x≤6）；（2）能安全通过，因为距中线2米处隧道高 (16)/(3) 米，大于车高4.8米。"},{"type":"note","title":"方法小结","text":"拱桥、隧道类建模题先由题意把文字条件翻译成点的坐标；判断能否通过时，要取货车最外沿对应位置的高度与车高比较，而不是取中线处（最高点）的高度。"},{"type":"list","title":"易错点","items":["单位漏写或单位不统一：应用题答案必须带单位，且过程中长度、质量、时间要统一（如秒与分钟、米与千米混用）会导致整题算错。","答非所问：题目问「降价多少元」却只答出最大利润，或问「售价是多少」却只答出降价的百分率，这类失分极其常见。","分式方程不检验：解出后既不检验分母是否为零，也不检验是否符合实际意义（如人数必须是正整数）。","增长率方向搞反：该用 $(1-x)$ 的写成 $(1+x)$，或把两次不同的变化率当成平方模型处理。","漏写自变量的取值范围：利润、面积等实际问题中的自变量都由实际意义限定，不写范围即使算对最值也算不完整。","读题时漏掉关键数据：精确度要求（如精确到0.01米）、角度值、参考数据（如 $\\sin10^\\circ\\approx0.174$）没有用上或误用，导致最终答案偏差很大。"]},{"type":"list","title":"解题方法","items":["读题三行法：把长文字题干压缩成「已知什么、求什么、用什么关系」三行，先理清结构再动笔建模，避免边读边算导致信息遗漏。","先定模型再设未知数：判断题目属于增长率、利润、工程行程、测量建模还是规律探究，模型一旦确定，设元方式与方程形式就基本确定。","数值先估算：在动笔前对答案做数量级估计（如降价百分率应比一半小、上升高度应小于斜坡长），算完可快速校验合理性。","取值范围与单位两件事写在最后：检查环节固定做两个动作，确认自变量范围是否写出、答案是否带单位并符合实际意义。","规律探究先列项再找差：写出前三到五项具体数值，比较一阶差；若差恒定用等差通项，若差成等差则考虑二次型，最后务必用已知项验证。","新定义题边读边标注：把材料中的定义逐句翻译成数学条件并标在图上，把操作步骤对应的等量关系逐一写出，再化归为相似或函数问题。"]}],"questions":[{"id":"m-exa-yingyong-tuili-q1","type":"choice","stem":"某商品原价100元，连续两次以相同的百分率降价后售价为81元，则每次降价的百分率为（　）","answer":"B","explain":"设每次降价百分率为 x，由题意得 100(1-x)²=81，即 (1-x)²=0.81，开平方得 1-x=0.9 或 1-x=-0.9，解得 x=0.1 或 x=1.9。由实际意义知 0<x<1，舍去 x=1.9，故 x=0.1=10\\%。故选B。","options":["9\\%","10\\%","19\\%","20\\%"],"difficulty":2,"tags":["增长率","一元二次方程应用"]},{"id":"m-exa-yingyong-tuili-q2","type":"fill","stem":"某商品每件进价40元，原售价每件60元时每天售出100件。每件售价每降低1元，每天销量增加10件。设每件降价 x 元，则每天销售利润 W（元）关于 x 的函数关系式为 W=____（用含 x 的最简二次三项式表示）。","answer":"-10x^2+100x+2000|-10x²+100x+2000","explain":"降价 x 元后，每件利润为 (60-x)-40=(20-x) 元，每天销量为 (100+10x) 件。故 W=(20-x)(100+10x)=2000+200x-100x-10x²=-10x²+100x+2000。配方得 W=-10(x-5)²+2250，故降价5元时利润最大，为2250元。","difficulty":2,"tags":["销售利润","二次函数应用"]},{"id":"m-exa-yingyong-tuili-q3","type":"fill","stem":"用火柴棒按规律搭图形：第1个图形用4根，第2个用7根，第3个用10根，每次增加的根数相同。则第 n 个图形用____根火柴棒（用含 n 的式子表示）。","answer":"3n+1","explain":"相邻两项之差恒为3，故为等差数列，首项 a₁=4，公差 d=3。由通项公式 a_n=4+3(n-1)=3n+1。验证：n=1 得4，n=2 得7，n=3 得10，均与已知相符。","difficulty":2,"tags":["规律探究","等差数列"]},{"id":"m-exa-yingyong-tuili-q4","type":"choice","stem":"某斜坡的坡角为 30^°。一人沿该斜坡的斜面向上走了100米，则他上升的高度为（　）","answer":"A","explain":"上升高度是竖直方向的位移，对应以100米斜面长为斜边的直角三角形中 30^° 角的对边，故 h=100sin30^°=100×12=50（米）。故选A。注意 503 米是水平方向的位移（用 cos30^° 计算），不要混淆；而坡度（坡比）是竖直高度与水平宽度之比，等于 tan30^°=(3)/(3)。","options":["50米","503米","(1003)/(3)米","100米"],"difficulty":2,"tags":["解直角三角形","坡度"]},{"id":"m-exa-yingyong-tuili-q5","type":"short","stem":"某果园引进智能采摘机器人以降低成本。已知用人工采摘某批水果的成本为 a 元，用机器人采摘的成本比人工降低 30\\%。（1）用含 a 的代数式表示机器人采摘的成本；（2）若采摘4000千克该水果，机器人单独完成比4个工人同时采摘少用1天，且机器人的采摘效率是一个工人的5倍，求这台机器人每天可采摘该水果多少千克。","answer":"（1）机器人采摘成本比人工降低 $30\\%$，故为 $a(1-30\\%)=0.7a$（元）。（2）设一个工人每天可采摘 $x$ 千克，则机器人每天可采摘 $5x$ 千克。采摘4000千克时，机器人单独所需时间为 $\\dfrac{4000}{5x}$ 天，4个工人同时采摘所需时间为 $\\dfrac{4000}{4x}$ 天。由「机器人比4个工人同时采摘少用1天」得 $\\dfrac{4000}{4x}-\\dfrac{4000}{5x}=1$。左边通分：$\\dfrac{1000}{x}-\\dfrac{800}{x}=1$，即 $\\dfrac{200}{x}=1$，解得 $x=200$。检验：$x=200\\neq0$，且符合实际意义。故机器人每天可采摘 $5\\times200=1000$ 千克。答：这台机器人每天可采摘该水果1000千克。","explain":"本题考查用代数式表示数量关系以及分式方程建模。第（1）问的关键是把「降低 30\\%」正确翻译为乘以 0.7，而不是乘以 0.3，这是最常见的失分点。第（2）问属于工程（采摘）问题，工作总量为4000千克，用「工作总量除以工作效率」表示工作时间：4个工人同时工作的效率为 4x，机器人的效率为 5x。列方程的方向由「机器人少用1天」确定，即工人用时减去机器人用时等于1。解出 x=200 后必须检验分母不为零且符合实际意义，最后还要转化为题目所问的「机器人每天采摘量」，即 5x=1000 千克，只答 x=200 属答非所问。","difficulty":3,"tags":["工程问题","分式方程","代数式表示"],"rubric":["第（1）问正确用含 a 的代数式表示成本为 0.7a 元，并理解「降低 30\\%」即乘以 0.7","第（2）问正确设未知数，并利用「效率是工人的5倍」表示出机器人的效率","分别正确表示出两种方式所需的时间（(4000)/(5x) 与 (4000)/(4x)）","根据时间差正确列出分式方程","正确解得 x=200，并求出机器人每天采摘1000千克","解后检验分母不为零且符合实际意义，最后写出完整的答句与单位"]},{"id":"m-exa-yingyong-tuili-z1","type":"choice","stem":"甲、乙两地相距300千米。一辆货车从甲地出发前往乙地，速度为60千米/时。货车出发1小时后，一辆轿车从甲地出发沿同一路线追赶，速度为90千米/时。当轿车追上货车时，轿车距乙地还有（　）","answer":"D","explain":"轿车出发时，货车已行驶 60×1=60 千米。设轿车出发 t 小时后追上货车，则轿车行驶 90t 千米，货车共行驶 60(t+1) 千米，由「追上」知两车路程相等，得 90t=60(t+1)，解得 t=2。此时轿车行驶 90×2=180 千米，距乙地还有 300-180=120 千米。故选D。易错点：忽略货车先出发的1小时而误列 90t=60t；或把180千米误当作距乙地的距离，答非所问。","options":["100千米","140千米","180千米","120千米"],"difficulty":2,"tags":["行程问题","一元一次方程应用"]},{"id":"m-exa-yingyong-tuili-z2","type":"short","stem":"某公司生产并销售一种产品，每件成本30元。按规定每件售价不低于40元且不高于60元。市场调查发现：售价为40元/件时，每周可售出400件；售价每提高1元，每周销量减少10件。（1）求每周销量 y（件）与售价 x（元/件）之间的函数关系式；（2）当售价为多少元时，每周销售利润最大？最大利润是多少元？（3）若某一周的销售利润为6000元，求该周产品的售价。","answer":"（1）由「售价为40元/件时售出400件，每提高1元减少10件」得 $y=400-10(x-40)=-10x+800$（$40\\leq x\\leq60$）。（2）每周利润 $W=(x-30)(-10x+800)=-10x^{2}+1100x-24000=-10(x-55)^{2}+6250$。因为 $55$ 在 $40\\leq x\\leq60$ 范围内，所以当 $x=55$ 时 $W$ 取最大值6250，即售价为55元/件时每周利润最大，最大利润为6250元。（3）由 $-10x^{2}+1100x-24000=6000$ 得 $x^{2}-110x+3000=0$，即 $(x-50)(x-60)=0$，解得 $x=50$ 或 $x=60$，均在规定范围内。答：该周产品的售价为50元/件或60元/件。","explain":"本题是「利润模型」的完整压轴。第（1）问用「基准销量减去10乘以涨价量」表示销量，自变量范围由「售价不低于40元且不高于60元」直接给出，必须写出。第（2）问套用「总利润 = 每件利润 × 销量」，每件利润为 (x-30)，配方前先确认顶点横坐标 x=55 在范围内，故最大值在顶点取得；若越界则要改比端点函数值。第（3）问是逆向设问：把 W=6000 代入整理成一元二次方程求解，得到的两个根都要保留并逐一检验是否在规定范围内，只答一个会丢解。","difficulty":3,"tags":["销售利润","二次函数应用","一元二次方程应用"],"rubric":["正确写出 y=-10x+800（40≤ x≤60），并列出 W=(x-30)(-10x+800)","配方求得最大利润6250元，并说明 x=55 在取值范围内","由 W=6000 解得 x=50 或 x=60，两个解均保留、检验并写出完整答句"]}]}];
